INSERT INTO `component_items` (`id`, `name`, `category`, `stock`, `price`, `description`, `how_to_use`, `snippet`, `created_at`, `updated_at`) VALUES
(1, 'React useState Hook Best Practices', 'Frontend', 1, 0.00, 'การใช้งาน useState ใน React สำหรับจัดการสถานะ (State) ของคอมโพเนนต์อย่างมีประสิทธิภาพ', 'ใช้เมื่อต้องการเก็บค่าข้อมูลที่เปลี่ยนแปลงได้ในหน้าจอ เช่น ฟอร์ม หรือปุ่มเปิด/ปิด Modal', 'const [isOpen, setIsOpen] = useState(false);\n\nconst toggleModal = () => {\n  setIsOpen(!isOpen);\n};', '2026-08-21 12:41:20', '2026-08-21 12:41:20'),
(2, 'Laravel Eloquent Relationships: One-to-Many', 'Backend', 1, 0.00, 'การเชื่อมโยงความสัมพันธ์ระหว่างตารางในฐานข้อมูลแบบ หนึ่งต่อหลาย (One-to-Many) ผ่าน Laravel Eloquent', 'ใช้เมื่อผู้ใช้ 1 คนสามารถมีโพสต์หรือรายการโค้ดได้หลายรายการ', 'public function items() {\n    return $this->hasMany(ComponentItem::class);\n}', '2026-08-21 12:41:20', '2026-08-21 12:41:20'),
(3, 'JavaScript Array Map Method', 'Frontend', 1, 0.00, 'ฟังก์ชันสำหรับวนลูปแปลงข้อมูลในอาเรย์ (Array) เพื่อแสดงผลออกมาเป็น UI คอมโพเนนต์', 'ใช้แสดงรายการการ์ดข้อมูล (Cards) หรือตารางใน React แทนการใช้คำสั่ง For Loop ปกติ', 'const items = [1, 2, 3, 4];\nconst listItems = items.map((num) => <li key={num}>{num * 2}</li>);', '2026-08-21 12:41:20', '2026-08-21 12:41:20'),
(4, 'SQL GROUP BY and COUNT', 'Database', 1, 0.00, 'คำสั่งจัดกลุ่มข้อมูลและนับจำนวนเรคคอร์ดในฐานข้อมูล MySQL', 'ใช้สรุปรายงาน เช่น ต้องการนับว่าในแต่ละหมวดหมู่ (Category) มีโค้ดอยู่กี่รายการ', 'SELECT category, COUNT(*) as total \nFROM component_items \nGROUP BY category;', '2026-08-21 12:41:20', '2026-08-21 12:41:20'),
(5, 'Tailwind CSS Flexbox Center Layout', 'Frontend', 1, 0.00, 'เทคนิคการจัดวางตำแหน่งไอเทมให้อยู่กึ่งกลางหน้าจอทั้งแนวตั้งและแนวนอนด้วย Tailwind CSS', 'ใช้จัดหน้าจอ Login, หน้า Welcome หรือจัดกล่องข้อความให้อยู่กลางจอเป๊ะๆ', '<div className=\"flex items-center justify-center min-h-screen bg-slate-950\">\n  <div className=\"text-white font-bold\">Center Content</div>\n</div>', '2026-08-21 12:41:20', '2026-08-21 12:41:20'),
(6, 'Responsive Navbar with Tailwind CSS', 'Frontend', 1, 0.00, 'สร้างแถบเมนูด้านบนเว็บไซต์ (Navbar) ที่ปรับขนาดอัตโนมัติ', 'นำไปวางเป็นส่วน Header หลักของโปรเจกต์เว็บแอปพลิเคชัน', 'export default function Navbar() {\n  return (\n    <nav className=\"flex justify-between items-center px-6 py-4 bg-slate-900 text-white\">\n      <div>MyBrand</div>\n    </nav>\n  );\n}', '2026-08-21 12:41:33', '2026-08-21 12:41:33'),
(7, 'Laravel Sanctum Authentication', 'Backend', 1, 0.00, 'ระบบยืนยันตัวตนสำหรับสร้าง API ด้วย Laravel Sanctum', 'ใช้เป็น Controller หลักในการตรวจสอบสิทธิ์ผู้ใช้งาน', 'public function login(Request $request) {\n    $user = User::where(\'email\', $request->email)->first();\n    return response()->json([\'message\' => \'Success\', \'user\' => $user]);\n}', '2026-08-21 12:41:33', '2026-08-21 12:41:33'),
(8, 'Database Indexing', 'Database', 1, 0.00, 'คำสั่งสร้าง Index บนคอลัมน์เพื่อเร่งความเร็วในการค้นหา', 'ใช้เมื่อฐานข้อมูลมีขนาดใหญ่ขึ้นและระบบเริ่มค้นหาช้าลง', 'CREATE INDEX idx_component_search ON component_items(name, category);', '2026-08-21 12:41:33', '2026-08-21 12:41:33'),
(9, 'TCP/IP 3-Way Handshake', 'Networking', 1, 0.00, 'กระบวนการเชื่อมต่อเครือข่ายระหว่าง Client และ Server', 'ใช้ทำความเข้าใจการเชื่อมต่อเครือข่ายและระบบ API', '[Client] -- SYN --> [Server]\n[Client] <- SYN-ACK - [Server]\n[Client] -- ACK --> [Server]', '2026-08-21 12:41:33', '2026-08-21 12:41:33'),
(10, 'MVC Architecture Pattern', 'Architecture', 1, 0.00, 'สถาปัตยกรรมซอฟต์แวร์แบ่งเป็น Model, View และ Controller', 'ใช้เป็นโครงสร้างหลักในการออกแบบโปรเจกต์ Full-stack', 'User -> Controller -> Model (Database) -> View (UI)', '2026-08-21 12:41:33', '2026-08-21 12:41:33'),
(11, 'React useEffect Lifecycle', 'Frontend', 1, 0.00, 'จัดการ Side Effects ใน React เช่น การดึงข้อมูลจาก API', 'ใช้เมื่อต้องการโหลดข้อมูลตอนหน้าเว็บเริ่มทำงาน หรือเฝ้าดูการเปลี่ยนแปลงของ State', 'useEffect(() => {\n  fetchData();\n}, []);', '2026-08-21 12:41:51', '2026-08-21 12:41:51'),
(12, 'Laravel Middleware Auth', 'Backend', 1, 0.00, 'ตรวจสอบสิทธิ์ผู้ใช้งานก่อนเข้าถึง Route', 'ใช้ปกป้องหน้า Dashboard ไม่ให้คนไม่ได้ล็อกอินเข้าดูได้', 'Route::middleware([\'auth\'])->group(function () {\n  Route::get(\'/dashboard\', ...);\n});', '2026-08-21 12:41:51', '2026-08-21 12:41:51'),
(13, 'MySQL Subquery', 'Database', 1, 0.00, 'การดึงข้อมูลโดยใช้ Query ซ้อน Query', 'ใช้เมื่อต้องการกรองข้อมูลโดยอิงจากผลลัพธ์ของอีกตาราง', 'SELECT name FROM items WHERE price > (SELECT AVG(price) FROM items);', '2026-08-21 12:41:51', '2026-08-21 12:41:51'),
(14, 'REST API DELETE Method', 'Networking', 1, 0.00, 'การส่งคำสั่งลบข้อมูลผ่าน HTTP Protocol', 'ใช้สำหรับทำระบบลบข้อมูล (Delete Record) ผ่าน API', 'axios.delete(\'/api/items/1\');', '2026-08-21 12:41:51', '2026-08-21 12:41:51'),
(15, 'Clean Architecture Concept', 'Architecture', 1, 0.00, 'การออกแบบซอฟต์แวร์ให้แยกส่วนประกอบออกจากกัน', 'ใช้เพื่อลดความซับซ้อนและเพิ่มการทดสอบโค้ด (Testing)', 'Layer: Entity -> UseCase -> Controller -> Infrastructure', '2026-08-21 12:41:51', '2026-08-21 12:41:51'),
(16, 'React Context API', 'Frontend', 1, 0.00, 'การส่งผ่านข้อมูลโดยไม่ต้องใช้ Props Drilling', 'ใช้สำหรับจัดการสถานะ Global เช่น Theme หรือ User Profile', 'const ThemeContext = createContext();', '2026-08-21 12:41:51', '2026-08-21 12:41:51'),
(17, 'Laravel Service Container', 'Backend', 1, 0.00, 'การจัดการ Dependency Injection ใน Laravel', 'ใช้จัดการคลาสที่ซับซ้อนเพื่อให้โค้ดสะอาดขึ้น', '$this->app->bind(Service::class, function ($app) { return new Service(); });', '2026-08-21 12:41:51', '2026-08-21 12:41:51'),
(18, 'SQL Inner Join', 'Database', 1, 0.00, 'ดึงข้อมูลที่สัมพันธ์กันระหว่าง 2 ตาราง', 'ใช้ดึงชื่อผู้ใช้คู่กับชื่อบทความที่เขียน', 'SELECT users.name, posts.title FROM users INNER JOIN posts ON users.id = posts.user_id;', '2026-08-21 12:41:51', '2026-08-21 12:41:51'),
(19, 'HTTP Status Codes 404', 'Networking', 1, 0.00, 'รหัสสถานะเมื่อไม่พบข้อมูลที่ร้องขอ', 'ใช้ส่งกลับไปบอกหน้าบ้านว่า URL นี้ไม่มีอยู่จริง', 'response()->json([\'error\' => \'Not Found\'], 404);', '2026-08-21 12:41:51', '2026-08-21 12:41:51'),
(20, 'Microservices vs Monolith', 'Architecture', 1, 0.00, 'เปรียบเทียบการออกแบบระบบแบบรวมศูนย์และแบบแยกส่วน', 'ใช้เลือกว่าโปรเจกต์ขนาดไหนควรใช้สถาปัตยกรรมอะไร', 'Monolith = รวมทุกอย่างไว้ที่เดียว, Microservices = แยก Service ตามฟังก์ชัน', '2026-08-21 12:41:51', '2026-08-21 12:41:51'),
(21, 'React useMemo Hook', 'Frontend', 1, 0.00, 'ช่วยจำค่าที่คำนวณแล้วเพื่อเพิ่มประสิทธิภาพ', 'ใช้เมื่อมีการคำนวณหนักๆ ใน Component', 'const memoizedValue = useMemo(() => compute(a, b), [a, b]);', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(22, 'Laravel Route Grouping', 'Backend', 1, 0.00, 'การจัดกลุ่ม Route เพื่อให้จัดการได้ง่าย', 'ใช้สำหรับทำระบบที่ต้องผ่าน Middleware หลายตัว', 'Route::prefix(\'admin\')->middleware(\'auth\')->group(function() { ... });', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(23, 'SQL Inner Join Basics', 'Database', 1, 0.00, 'การดึงข้อมูลจากสองตารางที่สัมพันธ์กัน', 'ใช้เชื่อมต่อตาราง Users กับ Posts', 'SELECT * FROM users INNER JOIN posts ON users.id = posts.user_id;', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(24, 'TCP/IP Model Layers', 'Networking', 1, 0.00, 'ลำดับชั้นของโปรโตคอลในระบบเครือข่าย', 'ใช้ในการออกแบบและแก้ไขปัญหา Network', 'Application, Transport, Internet, Network Access', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(25, 'MVC Pattern Explained', 'Architecture', 1, 0.00, 'โครงสร้างการทำงานแบบ Model-View-Controller', 'ใช้เป็นพิมพ์เขียวในการจัดการโปรเจกต์ขนาดใหญ่', 'Model: Data, View: UI, Controller: Logic', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(26, 'React useReducer Hook', 'Frontend', 1, 0.00, 'ใช้จัดการ State ที่ซับซ้อนแทน useState', 'เหมาะสำหรับ State ที่มีหลายค่าสัมพันธ์กัน', 'const [state, dispatch] = useReducer(reducer, initialState);', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(27, 'Laravel Eloquent Scopes', 'Backend', 1, 0.00, 'การสร้าง Query ที่ใช้ซ้ำได้ใน Model', 'ใช้กรองข้อมูลเช่น เฉพาะโพสต์ที่ถูกเผยแพร่แล้ว', 'public function scopePublished($query) { return $query->where(\'status\', \'published\'); }', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(28, 'SQL Index Optimization', 'Database', 1, 0.00, 'การสร้าง Index เพื่อความเร็วในการค้นหา', 'ใช้กับคอลัมน์ที่ถูกค้นหาบ่อย', 'CREATE INDEX idx_user_email ON users(email);', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(29, 'DNS Resolution Process', 'Networking', 1, 0.00, 'ขั้นตอนการแปลง Domain Name เป็น IP Address', 'ใช้อธิบายการทำงานของระบบเครือข่าย', 'Browser -> Cache -> Resolver -> Root Server', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(30, 'Microservices Architecture', 'Architecture', 1, 0.00, 'การแบ่งระบบเป็นบริการย่อยๆ', 'ใช้ขยายระบบงานขนาดใหญ่ได้ดีกว่า Monolith', 'แต่ละ Service มี Database ของตัวเอง', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(31, 'React Prop Drilling Problem', 'Frontend', 1, 0.00, 'ปัญหาการส่ง Props ผ่าน Component ลึกๆ', 'ใช้แก้ปัญหาด้วย Context API หรือ Redux', 'ไม่ควรส่ง Props เกิน 3-4 ชั้น', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(32, 'Laravel Form Validation', 'Backend', 1, 0.00, 'การตรวจสอบความถูกต้องของข้อมูลจากผู้ใช้', 'ใช้ป้องกันข้อมูลขยะหรือข้อมูลที่ไม่ปลอดภัย', '$request->validate([\'email\' => \'required|email\']);', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(33, 'SQL Transactions', 'Database', 1, 0.00, 'การจัดการการทำงานของฐานข้อมูลแบบกลุ่ม', 'ใช้เพื่อความปลอดภัย เช่น การโอนเงิน', 'START TRANSACTION; ... COMMIT;', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(34, 'HTTP/HTTPS Protocol', 'Networking', 1, 0.00, 'โปรโตคอลสำหรับการส่งข้อมูลบนเว็บ', 'HTTPS มีการเข้ารหัสข้อมูลที่ปลอดภัยกว่า', 'HTTP = Port 80, HTTPS = Port 443', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(35, 'Design Patterns: Singleton', 'Architecture', 1, 0.00, 'รูปแบบการออกแบบให้มีคลาสเพียงอินสแตนซ์เดียว', 'ใช้จัดการฐานข้อมูลหรือตั้งค่าระบบ', 'private static $instance; public static function getInstance()...', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(36, 'React Memoization', 'Frontend', 1, 0.00, 'การป้องกันการ Render Component ซ้ำโดยไม่จำเป็น', 'ใช้เพิ่มความเร็วในหน้าเว็บที่แสดงผลเยอะๆ', 'const MemoizedComponent = React.memo(Component);', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(37, 'Laravel Queue System', 'Backend', 1, 0.00, 'การทำงานเบื้องหลังเพื่อประมวลผลงานหนัก', 'ใช้ส่งอีเมลหรือประมวลผลไฟล์ขนาดใหญ่', 'dispatch(new SendEmailJob($user));', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(38, 'SQL Primary Key', 'Database', 1, 0.00, 'คีย์หลักที่กำหนดความเป็นเอกลักษณ์ของแถว', 'ทุกตารางควรมี Primary Key เพื่ออ้างอิง', 'id INT AUTO_INCREMENT PRIMARY KEY', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(39, 'IP Address v4 vs v6', 'Networking', 1, 0.00, 'มาตรฐานการระบุที่อยู่บนเครือข่าย', 'v6 มีจำนวน Address มากกว่า v4 มหาศาล', 'IPv4 = 32-bit, IPv6 = 128-bit', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(40, 'SOLID Principles', 'Architecture', 1, 0.00, 'หลักการออกแบบซอฟต์แวร์ให้ยืดหยุ่น', 'ใช้เพื่อการบำรุงรักษาโค้ดในระยะยาว', 'Single Responsibility, Open/Closed, Liskov, Interface, Dependency', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(41, 'React Custom Components', 'Frontend', 1, 0.00, 'การสร้างคอมโพเนนต์ที่นำกลับมาใช้ใหม่ได้', 'ลดการเขียนโค้ดซ้ำๆ ในหลายหน้า', 'function CustomButton({ text }) { return <button>{text}</button>; }', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(42, 'Laravel Authentication', 'Backend', 1, 0.00, 'ระบบตรวจสอบสิทธิ์ผู้ใช้งานสำเร็จรูป', 'ใช้จัดการระบบสมาชิกอย่างรวดเร็ว', 'php artisan make:auth', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(43, 'SQL Foreign Key', 'Database', 1, 0.00, 'การสร้างความสัมพันธ์ระหว่างตาราง', 'ใช้ตรวจสอบความถูกต้องของข้อมูล', 'FOREIGN KEY (user_id) REFERENCES users(id)', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(44, 'Subnet Masking', 'Networking', 1, 0.00, 'การแบ่งเครือข่ายย่อย', 'ใช้จัดการ IP Address ในองค์กรให้เป็นระเบียบ', '255.255.255.0 /24', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(45, 'Event-Driven Architecture', 'Architecture', 1, 0.00, 'ระบบที่ทำงานตามเหตุการณ์ที่เกิดขึ้น', 'ใช้ทำระบบแจ้งเตือนหรือระบบตอบโต้', 'Publisher -> Event -> Subscriber', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(46, 'React Portal', 'Frontend', 1, 0.00, 'การแสดงผล Component นอก DOM หลัก', 'ใช้สำหรับทำ Modal หรือ Tooltip ที่ลอยอยู่ด้านบน', 'ReactDOM.createPortal(child, container);', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(47, 'Laravel Blade Directives', 'Backend', 1, 0.00, 'คำสั่งควบคุมใน Template Engine ของ Laravel', 'ใช้แสดงเงื่อนไขหรือวนลูปในหน้า HTML', '@if($user) ... @endif', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
(48, 'SQL Aggregate Functions', 'Database', 1, 0.00, 'คำสั่งสำหรับคำนวณข้อมูล', 'ใช้หาค่าผลรวม, ค่าเฉลี่ย, ค่าสูงสุด', 'SUM(), AVG(), MAX(), MIN()', '2026-08-21 12:42:36', '2026-08-21 12:42:36'),
