(646, 'Laravel: API Resource Single Transform', 'Backend', 1, 0.00, 'การแปลงรูปแบบข้อมูลเดี่ยวสำหรับส่งออก API', 'ซ่อนฟิลด์ที่ไม่จำเป็นเช่นรหัสผ่านก่อนส่งออก', 'return new UserResource($user);', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(647, 'Laravel: Validation Custom Error Messages', 'Backend', 1, 0.00, 'การกำหนดข้อความแจ้งเตือนความผิดพลาดภาษาไทย', 'ปรับแต่งข้อความ Validate ให้เข้าใจง่าย', '$request->validate([\'email\' => \'required|email\'], [\'email.required\' => \'กรุณากรอกอีเมล\']);', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(648, 'Laravel: Storage URL Generation', 'Backend', 1, 0.00, 'การสร้างลิงก์เข้าถึงไฟล์ที่อัปโหลด', 'แปลงพาธไฟล์ในเซิร์ฟเวอร์ให้เป็น URL สำหรับแสดงผล', '$url = Storage::url($path);', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(649, 'Laravel: Carbon Date Manipulation', 'Backend', 1, 0.00, 'การจัดการวันและเวลาด้วยไลบรารี Carbon', 'คำนวณช่วงเวลา ตรวจสอบวันหมดอายุ หรือแปลงโซนเวลา', '$dt = Carbon::now()->addDays(7);', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(650, 'Laravel: Encryption and Decryption', 'Backend', 1, 0.00, 'การเข้ารหัสและถอดรหัสข้อความลับ', 'ความปลอดภัยระดับแอปพลิเคชันสำหรับข้อมูลเซนซิทีฟ', '$encrypted = Crypt::encryptString(\'Secret Data\');', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(651, 'Laravel: Response Stream Download', 'Backend', 1, 0.00, 'การดาวน์โหลดไฟล์ขนาดใหญ่แบบสตรีม', 'ประหยัดแรมเซิร์ฟเวอร์เวลาให้ผู้ใช้ดาวน์โหลดไฟล์รายงาน', 'return response()->download($path);', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(652, 'Laravel: Model Soft Deletes Restore', 'Backend', 1, 0.00, 'การกู้คืนข้อมูลที่ถูกลบแบบชั่วคราว', 'ดึงข้อมูลที่อยู่ในสถานะถังขยะกลับคืนมา', 'User::withTrashed()->find($id)->restore();', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(653, 'Laravel: Query Builder Aggregate Sum', 'Backend', 1, 0.00, 'การรวมยอดคำนวณตัวเลขด้วย Query Builder', 'หาผลรวมยอดขายหรือราคาเฉลี่ยอย่างรวดเร็ว', '$total = DB::table(\'orders\')->sum(\'amount\');', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(654, 'Laravel: Http Client With Headers', 'Backend', 1, 0.00, 'การยิง HTTP Request พร้อมแนบ Header', 'ใช้สื่อสารกับภายนอก API ที่ต้องใช้ Token ยืนยัน', '$response = Http::withToken(\'secret-token\')->get(\'https://api.site.com/data\');', '2026-08-21 13:09:39', '2026-08-21 13:09:39');
INSERT INTO `component_items` (`id`, `name`, `category`, `stock`, `price`, `description`, `how_to_use`, `snippet`, `created_at`, `updated_at`) VALUES
(655, 'Laravel: Config Retrieval Helper', 'Backend', 1, 0.00, 'การดึงค่าคอนฟิกจากไฟล์ในโฟลเดอร์ config', 'ใช้อ่านค่าตัวแปรตั้งค่าระบบ', '$timeout = config(\'services.stripe.timeout\');', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(656, 'Laravel: Env Environment Helper', 'Backend', 1, 0.00, 'การอ่านค่าตัวแปรจากไฟล์ .env', 'ใช้เช็คโหมดการทำงานหรือคีย์ API ภายนอก', '$debug = env(\'APP_DEBUG\', false);', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(657, 'Laravel: View Composer Shared Data', 'Backend', 1, 0.00, 'การส่งข้อมูลกลางไปให้ทุกหน้าเว็บ Template', 'ใช้แสดงชื่อผู้ใช้หรือการแจ้งเตือนทุกหน้าจอ', 'View::composer(\'*\', function ($view) { $view->with(\'appName\', \'Knowledge Base\'); });', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(658, 'Laravel: Blade Custom Directive', 'Backend', 1, 0.00, 'การสร้างคำสั่ง Blade Template ของตัวเอง', 'ลดความซ้ำซ้อนของการเขียนเงื่อนไขในหน้า HTML', 'Blade::directive(\'admin\', function () { return \"<?php if(auth()->check() && auth()->user()->isAdmin()): ?>\"; });', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(659, 'Laravel: Database Seed Factory Chain', 'Backend', 1, 0.00, 'การสร้างข้อมูลจำลองเชื่อมโยงความสัมพันธ์', 'สร้างข้อมูล User พร้อมโพสต์ลูกในคำสั่งเดียว', 'User::factory()->has(Post::factory()->count(3))->create();', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(660, 'Laravel: Route Fallback Handling', 'Backend', 1, 0.00, 'การจัดการเส้นทางเมื่อไม่พบ URL ที่เรียก', 'ใช้ทำหน้า Error 404 แบบกำหนดเอง', 'Route::fallback(function () { return response()->json([\'error\' => \'Not found\'], 404); });', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(661, 'Laravel: Maintenance Mode Bypass', 'Backend', 1, 0.00, 'การเปิดโหมดปิดปรับปรุงระบบชั่วคราว', 'บล็อกการเข้าใช้งานพร้อมยกเว้นไอพีแอดเดรสผู้ดูแลระบบ', 'php artisan down --secret=\"my-bypass-token\"', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(662, 'Laravel: Queue Batching Progress', 'Backend', 1, 0.00, 'การติดตามสถานะงานกลุ่มคิวที่กำลังประมวลผล', 'ตรวจสอบเปอร์เซ็นต์ความคืบหน้าของงานเบื้องหลัง', '$batch = Bus::findBatch($batchId); $progress = $batch->progress();', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(663, 'Laravel: Rate Limiter Custom Definition', 'Backend', 1, 0.00, 'การตั้งค่าจำกัดโควตาการเรียกใช้งาน API เฉพาะจุด', 'ป้องกันบอทถล่มระบบฟอร์มล็อกอิน', 'RateLimiter::for(\'login\', function (Request $request) { return Limit::perMinute(5)->by($request->ip()); });', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(664, 'Laravel: Database Index Migration', 'Backend', 1, 0.00, 'การเพิ่ม Index ให้คอลัมน์ผ่าน Migration', 'เร่งความเร็วการค้นหาข้อมูลในตารางขนาดใหญ่', '$table->index(\'email\');', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(665, 'Laravel: Model Without Events', 'Backend', 1, 0.00, 'การบันทึกข้อมูลโดยไม่ให้ Event ทำงานชั่วคราว', 'ป้องกันการเรียกใช้งาน Listener ซ้ำซ้อนตอนเซฟ', 'User::withoutEvents(function () use ($user) { $user->save(); });', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(666, 'Laravel: Package Service Provider', 'Backend', 1, 0.00, 'การลงทะเบียนแพ็กเกจเสริมเข้าสู่ระบบหลัก', 'เชื่อมต่อคลาสและคอนฟิกภายนอกเข้ามาใน Laravel', 'public function register() { $this->app->bind(...); }', '2026-08-21 13:09:39', '2026-08-21 13:09:39'),
(667, 'Laravel: Eloquent Where Between', 'Backend', 1, 0.00, 'การกรองข้อมูลตัวเลขหรือวันที่ในช่วงที่กำหนด', 'ใช้หาข้อมูลที่อยู่ระหว่างค่าเริ่มต้นและสิ้นสุด', 'User::whereBetween(\'age\', [18, 30])->get();', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(668, 'Laravel: Eloquent Where Null', 'Backend', 1, 0.00, 'การกรองข้อมูลที่เป็นค่าว่าง (NULL)', 'ใช้หาเรคคอร์ดที่ยังไม่ได้ระบุข้อมูลฟิลด์นั้น', 'User::whereNull(\'deleted_at\')->get();', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(669, 'Laravel: Eloquent Where In', 'Backend', 1, 0.00, 'การกรองข้อมูลโดยเทียบกับอาเรย์ของค่าที่กำหนด', 'ใช้เลือกข้อมูลที่มี ID ตรงกับรายการในอาเรย์', 'User::whereIn(\'id\', [1, 2, 3])->get();', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(670, 'Laravel: Eloquent Increment Value', 'Backend', 1, 0.00, 'การเพิ่มค่าตัวเลขในฐานข้อมูลทันที', 'ใช้นับจำนวนยอดวิวหรือคะแนนโดยไม่ต้องดึงมาบวกเอง', 'Post::where(\'id\', 1)->increment(\'views\');', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(671, 'Laravel: Eloquent Decrement Value', 'Backend', 1, 0.00, 'การลดค่าตัวเลขในฐานข้อมูลทันที', 'ใช้ลดจำนวนสต็อกสินค้าในคลัง', 'Product::where(\'id\', 1)->decrement(\'stock\', 1);', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(672, 'Laravel: Eloquent First Or Create', 'Backend', 1, 0.00, 'ค้นหาข้อมูล ถ้าไม่พบให้สร้างใหม่ทันที', 'ใช้จัดการข้อมูลที่ไม่ซ้ำโดยอัตโนมัติ', 'User::firstOrCreate([\'email\' => \'test@mail.com\'], [\'name\' => \'Test\']);', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(673, 'Laravel: Eloquent Update Or Create', 'Backend', 1, 0.00, 'ค้นหาแล้วอัปเดต หรือถ้าไม่มีให้สร้างใหม่', 'ใช้ซิงค์ข้อมูลจากภายนอกเข้าฐานข้อมูล', 'User::updateOrCreate([\'email\' => \'test@mail.com\'], [\'name\' => \'Updated\']);', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(674, 'Laravel: Eloquent Touch Timestamp', 'Backend', 1, 0.00, 'การอัปเดตเวลา updated_at ของโมเดล', 'ใช้บังคับอัปเดตเวลาแก้ไขล่าสุดของตารางแม่', '$post->touch();', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(675, 'Laravel: Eloquent Pluck Column', 'Backend', 1, 0.00, 'การดึงค่าเฉพาะคอลัมน์เดียวออกมาเป็นอาเรย์', 'ใช้ดึงรายชื่ออีเมลหรือชื่อทั้งหมดอย่างรวดเร็ว', '$emails = User::pluck(\'email\');', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(676, 'Laravel: Eloquent Value Retrieval', 'Backend', 1, 0.00, 'การดึงค่าเดียวจากเรคคอร์ดแรกที่เจอ', 'ใช้ดึงชื่อหรือค่าฟิลด์เดี่ยวๆ โดยไม่ต้องโหลดโมเดล', '$name = User::where(\'id\', 1)->value(\'name\');', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(677, 'Laravel: Query Builder Raw Expressions', 'Backend', 1, 0.00, 'การเขียนคำสั่ง SQL ดิบร่วมกับ Query Builder', 'ใช้คำนวณหรือใช้ฟังก์ชันเฉพาะของฐานข้อมูล', 'DB::table(\'users\')->select(DB::raw(\'count(*) as total, status\'))->groupBy(\'status\')->get();', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(678, 'Laravel: Query Builder Having Clause', 'Backend', 1, 0.00, 'การกรองข้อมูลหลังจากการจัดกลุ่ม GROUP BY', 'ใช้กรองผลลัพธ์จากการนับหรือรวมกลุ่ม', 'DB::table(\'orders\')->groupBy(\'user_id\')->having(\'total\', \'>\', 100)->get();', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(679, 'Laravel: Database Transaction Rollback', 'Backend', 1, 0.00, 'การยกเลิกการทำงานเมื่อเกิดข้อผิดพลาด', 'ใช้ควบคุมความปลอดภัยของข้อมูลหลายตาราง', 'DB::rollBack();', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(680, 'Laravel: Schema Foreign Key Constraint', 'Backend', 1, 0.00, 'การสร้างความสัมพันธ์ระหว่างตารางผ่าน Migration', 'บังคับความถูกต้องของข้อมูลอ้างอิง', '$table->foreign(\'user_id\')->references(\'id\')->on(\'users\')->onDelete(\'cascade\');', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(681, 'Laravel: Schema Rename Table', 'Backend', 1, 0.00, 'การเปลี่ยนชื่อตารางในฐานข้อมูลผ่าน Migration', 'ใช้อัปเดตโครงสร้างเมื่อเปลี่ยนชื่อโมเดล', 'Schema::rename(\'old_name\', \'new_name\');', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(682, 'Laravel: Schema Drop TableIfExists', 'Backend', 1, 0.00, 'การลบตารางถ้ามีอยู่จริง', 'ใช้สำหรับเคลียร์โครงสร้างเก่าทิ้งใน Migration', 'Schema::dropIfExists(\'temp_table\');', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(683, 'Laravel: Request Validate with Messages', 'Backend', 1, 0.00, 'การตรวจสอบข้อมูลพร้อมกำหนดข้อความแจ้งเตือน', 'ปรับแต่งภาษาแจ้งเตือนข้อผิดพลาดให้เป็นไทย', '$request->validate([\'name\' => \'required\'], [\'name.required\' => \'กรุณากรอกชื่อ\']);', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(684, 'Laravel: Request Filled and Missing', 'Backend', 1, 0.00, 'การตรวจสอบว่ามีค่าถูกส่งมาและไม่ว่างเปล่า', 'ใช้เช็คฟิลด์สำคัญในฟอร์ม', 'if ($request->filled(\'email\')) { ... }', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(685, 'Laravel: Response Json Status Code', 'Backend', 1, 0.00, 'การส่งคืน JSON พร้อมระบุรหัสสถานะ HTTP', 'กำหนดสถานะสำเร็จหรือข้อผิดพลาดให้ชัดเจน', 'return response()->json([\'message\' => \'Created\'], 201);', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(686, 'Laravel: Response Download File Stream', 'Backend', 1, 0.00, 'การดาวน์โหลดไฟล์จากเซิร์ฟเวอร์', 'ส่งไฟล์เอกสารหรือรายงานให้ผู้ใช้ดาวน์โหลด', 'return response()->download(storage_path(\'app/file.pdf\'));', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(687, 'Laravel: Storage Disk Custom Access', 'Backend', 1, 0.00, 'การเข้าถึง Storage Disk เฉพาะเจาะจง', 'ใช้จัดการไฟล์บน S3 หรือ Local Disk', '$exists = Storage::disk(\'s3\')->exists(\'file.jpg\');', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(688, 'Laravel: Hash Check Info', 'Backend', 1, 0.00, 'การตรวจสอบข้อมูลการแฮชรหัสผ่าน', 'ดูว่ารหัสผ่านจำเป็นต้องถูกแฮชใหม่หรือไม่', '$info = Hash::info($hashedValue);', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(689, 'Laravel: Auth Via Remember Token', 'Backend', 1, 0.00, 'การจัดการระบบจดจำการเข้าสู่ระบบ', 'ให้ผู้ใช้ค้างสถานะล็อกอินไว้แม้ปิดเบราว์เซอร์', 'Auth::login($user, $remember = true);', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(690, 'Laravel: Middleware Terminate Method', 'Backend', 1, 0.00, 'เมธอดทำงานหลังจาก Response ถูกส่งไปแล้ว', 'ใช้บันทึก Log เวลาการประมวลผลระบบหลังบ้าน', 'public function terminate($request, $response) { ... }', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(691, 'Laravel: Route Pattern Constraints', 'Backend', 1, 0.00, 'การกำหนดกฎเกณฑ์รูปแบบตัวแปรใน Route', 'บังคับให้พารามิเตอร์ต้องเป็นตัวเลขเท่านั้น', 'Route::get(\'/user/{id}\', ...)->where(\'id\', \'[0-9]+\');', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
(692, 'Laravel: Redirect Back with Input', 'Backend', 1, 0.00, 'การส่งผู้ใช้กลับหน้าเดิมพร้อมข้อมูลฟอร์มเก่า', 'ให้ผู้ใช้ไม่ต้องพิมพ์ข้อมูลใหม่ซ้ำเมื่อเกิด Error', 'return back()->withInput();', '2026-08-21 13:10:30', '2026-08-21 13:10:30'),
