(842, 'Bootstrap 5: Offcanvas Sidebar Drawer', 'Frontend', 1, 0.00, 'แถบเมนูด้านข้างที่สไลด์โผล่เข้ามาจากขอบจอ', 'ใช้ทำเมนูมือถือหรือตะกร้าสินค้าแบบสไลด์', '<div class=\"offcanvas offcanvas-start\" tabindex=\"-1\" id=\"offcanvasExample\">...</div>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(843, 'Bootstrap 5: Form Controls Inputs', 'Frontend', 1, 0.00, 'การตกแต่งช่องกรอกข้อมูลฟอร์มมาตรฐาน', 'ใช้ทำฟอร์มรับข้อมูล ชื่อ อีเมล รหัสผ่าน', '<input type=\"email\" class=\"form-control\" placeholder=\"name@example.com\">', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(844, 'Bootstrap 5: Form Select Dropdown', 'Frontend', 1, 0.00, 'ช่องเลือกตัวเลือกดรอปดาวน์ฟอร์ม', 'ใช้ทำดรอปดาวน์เลือกจังหวัดหรือหมวดหมู่', '<select class=\"form-select\"><option>Open this select menu</option></select>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(845, 'Bootstrap 5: Form Checks and Radios', 'Frontend', 1, 0.00, 'ปุ่มติ๊กเลือก (Checkbox) และปุ่มเลือกวิทยุ (Radio)', 'ใช้ทำตัวเลือกสถานะหรือเพศในฟอร์ม', '<input class=\"form-check-input\" type=\"checkbox\" value=\"\" id=\"flexCheckDefault\">', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(846, 'Bootstrap 5: Form Range Sliders', 'Frontend', 1, 0.00, 'แถบสไลด์เลื่อนเลือกช่วงตัวเลข', 'ใช้ทำระบบปรับระดับราคาหรือความดัง', '<input type=\"range\" class=\"form-range\" id=\"customRange1\">', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(847, 'Bootstrap 5: Input Groups Addons', 'Frontend', 1, 0.00, 'การรวมข้อความหรือไอคอนติดกับช่องกรอกข้อมูล', 'ใช้ทำช่องใส่รหัสสกุลเงินหรือชื่อเว็บไซต์', '<div class=\"input-group mb-3\"><span class=\"input-group-text\">@</span><input type=\"text\" class=\"form-control\"></div>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(848, 'Bootstrap 5: Floating Labels Forms', 'Frontend', 1, 0.00, 'ป้ายชื่อฟอร์มลอยตัวเมื่อมีการพิมพ์ข้อความ', 'เพิ่มความสวยงามทันสมัยให้ฟอร์มรับข้อมูล', '<div class=\"form-floating mb-3\"><input type=\"email\" class=\"form-control\"><label>Email address</label></div>', '2026-08-21 13:13:53', '2026-08-21 13:13:53');
INSERT INTO `component_items` (`id`, `name`, `category`, `stock`, `price`, `description`, `how_to_use`, `snippet`, `created_at`, `updated_at`) VALUES
(849, 'Bootstrap 5: Form Validation Styles', 'Frontend', 1, 0.00, 'การแสดงผลสถานะตรวจสอบความถูกต้องของฟอร์ม', 'แสดงกรอบสีเขียวหรือแดงตามผลการกรอกข้อมูล', '<form class=\"was-validated\"><input type=\"text\" class=\"form-control\" required></form>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(850, 'Bootstrap 5: Close Button Component', 'Frontend', 1, 0.00, 'ปุ่มกากบาทสำหรับปิดกล่องแจ้งเตือนหรือโมดอล', 'ใช้วางมุมขวาบนของหน้าต่างป๊อปอัพ', '<button type=\"button\" class=\"btn-close\" aria-label=\"Close\"></button>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(851, 'Bootstrap 5: Ratio Video Embedder', 'Frontend', 1, 0.00, 'การล็อคสัดส่วนหน้าจอวิดีโอ (เช่น 16:9)', 'ใช้ฝังคลิป YouTube หรือสื่อวิดีโอไม่ให้เพี้ยน', '<div class=\"ratio ratio-16x9\"><iframe src=\"...\"></iframe></div>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(852, 'Bootstrap 5: Stacks Layout Helper', 'Frontend', 1, 0.00, 'เครื่องมือจัดเรียงเลย์เอาต์แนวตั้งและแนวนอนด่วน', 'ใช้คลาส vstack และ hstack จัดระเบียบไอเทม', '<div class=\"vstack gap-3\"><div>First item</div><div>Second item</div></div>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(853, 'Bootstrap 5: Colored Links Utilities', 'Frontend', 1, 0.00, 'การเปลี่ยนสีลิงก์ข้อความสำเร็จรูป', 'ใช้กำหนดสีลิงก์ให้เข้ากับธีมเว็บไซต์', '<a href=\"#\" class=\"link-success\">Success link</a>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(854, 'Bootstrap 5: Position Utilities', 'Frontend', 1, 0.00, 'การกำหนดตำแหน่งการจัดวาง (Absolute, Fixed, Sticky)', 'ใช้ตรึงตำแหน่งคอมโพเนนต์ให้อยู่มุมจอ', '<div class=\"position-absolute top-0 end-0\">...</div>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(855, 'Bootstrap 5: Borders Utilities', 'Frontend', 1, 0.00, 'การใส่เส้นขอบรอบคอมโพเนนต์หรือปรับความโค้งมน', 'ใช้เน้นกรอบกล่องคอนเทนต์ให้โดดเด่น', '<div class=\"border border-primary rounded-3\">...</div>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(856, 'Bootstrap 5: Shadow Effects', 'Frontend', 1, 0.00, 'การใส่เงาให้คอมโพเนนต์ดูมีมิติ (sm, lg, none)', 'ใช้ยกตัวการ์ดหรือปุ่มให้ดูลอยเด่นขึ้นมา', '<div class=\"shadow-lg p-3 mb-5 bg-body rounded\">...</div>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(857, 'Bootstrap 5: Text Truncation Text-Wrap', 'Frontend', 1, 0.00, 'การตัดข้อความยาวๆ ให้ลงท้ายด้วยจุดไข่ปลา (...)', 'ใช้ป้องกันข้อความล้นกรอบการแสดงผล', '<div class=\"text-truncate\" style=\"max-width: 150px;\">Long text...</div>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(858, 'Bootstrap 5: Visibility Toggle Classes', 'Frontend', 1, 0.00, 'การซ่อนหรือแสดงผลคอมโพเนนต์ (visible / invisible)', 'ใช้ควบคุมการมองเห็นโดยไม่กระทบพื้นที่เลย์เอาต์', '<div class=\"invisible\">Can not see this</div>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(859, 'Bootstrap 5: Screen Readers Accessibility', 'Frontend', 1, 0.00, 'การซ่อนข้อความสำหรับหน้าจออ่านหนังสือคนตาบอด', 'ช่วยให้เว็บไซต์ผ่านมาตรฐานการเข้าถึง (Accessibility)', '<span class=\"visually-hidden\">Loading...</span>', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(860, 'Bootstrap 5: Dark Mode Theme Support', 'Frontend', 1, 0.00, 'การเปิดใช้งานโหมดมืด (Dark Theme) ทั่วทั้งหน้าเว็บ', 'กำหนดค่าแอตทริบิวต์ที่แท็กหลักให้เว็บเปลี่ยนเป็นสีมืด', '<html data-bs-theme=\"dark\">', '2026-08-21 13:13:53', '2026-08-21 13:13:53'),
(861, 'Bootstrap 5: Grid Gutters Control', 'Frontend', 1, 0.00, 'การควบคุมระยะห่างระหว่างคอลัมน์ในกริด (g-0 ถึง g-5)', 'ใช้ปรับช่องว่างระหว่างคอลัมน์ให้แคบลงหรือกว้างขึ้นตามต้องการ', '<div class=\"row g-3\"><div class=\"col-md-6\">...</div></div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(862, 'Bootstrap 5: Grid Column Wrapping', 'Frontend', 1, 0.00, 'การตัดแถวคอลัมน์อัตโนมัติเมื่อเกิน 12 ช่อง', 'ดันคอลัมน์ที่เกินลงมาแสดงผลในบรรทัดถัดไป', '<div class=\"row\"><div class=\"col-8\">...</div><div class=\"col-5\">...</div></div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(863, 'Bootstrap 5: Grid Column Reordering', 'Frontend', 1, 0.00, 'การสลับตำแหน่งลำดับการแสดงผลคอลัมน์ (order)', 'จัดเรียงลำดับการแสดงผลบนหน้าจอโดยไม่ต้องแก้โครงสร้าง HTML', '<div class=\"col order-last\">First, but last</div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(864, 'Bootstrap 5: Grid Offset Columns', 'Frontend', 1, 0.00, 'การเว้นช่องว่างหน้าคอลัมน์ (offset)', 'ใช้ดันคอลัมน์ให้เยื้องไปทางขวาตามจำนวนช่องที่กำหนด', '<div class=\"col-md-4 offset-md-4\">Centered</div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(865, 'Bootstrap 5: Flex Align Items', 'Frontend', 1, 0.00, 'การจัดตำแหน่งแนวตั้งในระบบ Flexbox (align-items)', 'จัดให้ไอเทมชิดบน ตรงกลาง หรือชิดล่างในแถว', '<div class=\"d-flex align-items-center\">...</div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(866, 'Bootstrap 5: Flex Align Self', 'Frontend', 1, 0.00, 'การจัดตำแหน่งแนวตั้งเฉพาะตัวไอเทมเดี่ยวๆ', 'บังคับให้ไอเทมตัวเดียวในกลุ่มวางตำแหน่งต่างจากเพื่อน', '<div class=\"align-self-end\">Pushed to bottom</div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(867, 'Bootstrap 5: Flex Direction Classes', 'Frontend', 1, 0.00, 'การสลับทิศทางเรียงตัวไอเทม (row / column)', 'เปลี่ยนทิศทางการแสดงผลจากแนวนอนเป็นแนวตั้ง', '<div class=\"d-flex flex-column\">...</div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(868, 'Bootstrap 5: Flex Wrap Control', 'Frontend', 1, 0.00, 'การควบคุมการตัดบรรทัดของไอเทม (flex-wrap)', 'กำหนดว่าให้ไอเทมปัดตกบรรทัดใหม่เมื่อพื้นที่หมดหรือไม่', '<div class=\"d-flex flex-nowrap\">...</div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(869, 'Bootstrap 5: Flex Fill and Grow', 'Frontend', 1, 0.00, 'การขยายขนาดไอเทมให้เต็มพื้นที่ว่าง (flex-fill)', 'บังคับให้ไอเทมขยายตัวแบ่งพื้นที่ที่เหลือเท่าๆ กัน', '<div class=\"p-2 flex-fill\">Flex fill</div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(870, 'Bootstrap 5: Responsive Display Utilities', 'Frontend', 1, 0.00, 'การซ่อนหรือแสดงผลตามขนาดหน้าจอ (d-none, d-md-block)', 'กำหนดให้แสดงผลเฉพาะบนมือถือหรือคอมพิวเตอร์', '<div class=\"d-none d-lg-block\">Hide on mobile, show on desktop</div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(871, 'Bootstrap 5: Text Alignment Utilities', 'Frontend', 1, 0.00, 'การจัดตำแหน่งข้อความ (text-start, center, end)', 'จัดข้อความให้ชิดซ้าย กึ่งกลาง หรือชิดขวา', '<p class=\"text-end\">Right aligned text</p>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(872, 'Bootstrap 5: Text Transformation', 'Frontend', 1, 0.00, 'การแปลงรูปแบบตัวอักษร (lowercase, uppercase, capitalize)', 'บังคับแสดงผลตัวพิมพ์ใหญ่หรือพิมพ์เล็กโดยไม่ต้องแก้ข้อมูล', '<p class=\"text-uppercase\">Lower cased text</p>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(873, 'Bootstrap 5: Text Breaking & Wrapping', 'Frontend', 1, 0.00, 'การตัดคำยาวๆ ไม่ให้ล้นกรอบ (text-break)', 'บังคับให้คำศัพท์ยาวๆ ตัดบรรทัดลงมาแสดงผลด้านล่าง', '<p class=\"text-break\">Verylongwordthatwillnotfit...</p>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(874, 'Bootstrap 5: Font Weight and Italic', 'Frontend', 1, 0.00, 'การปรับความหนาตัวอักษรและตัวเอียง (fw-bold, fst-italic)', 'เน้นความโดดเด่นให้ข้อความสำคัญ', '<p class=\"fw-bold fst-italic\">Bold italic text</p>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(875, 'Bootstrap 5: Line Height Utilities', 'Frontend', 1, 0.00, 'การกำหนดระยะห่างความสูงบรรทัด (lh-1, lh-sm, lh-lg)', 'ปรับระยะห่างระหว่างบรรทัดข้อความให้อ่านง่าย', '<p class=\"lh-sm\">This is a long paragraph...</p>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(876, 'Bootstrap 5: List Unstyled and Inline', 'Frontend', 1, 0.00, 'การลบสัญลักษณ์จุดหน้าลิสต์หรือเรียงแนวนอน', 'ทำเมนูน้องสกลหรือรายการลิงก์แบบไม่มีจุดไข่ปลา', '<ul class=\"list-unstyled\"><li>This is a list</li></ul>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(877, 'Bootstrap 5: Figure and Captions', 'Frontend', 1, 0.00, 'การแสดงรูปภาพพร้อมข้อความอธิบายใต้ภาพ', 'จัดรูปแบบรูปภาพประกอบบทความให้ดูเป็นระเบียบ', '<figure class=\"figure\"><img src=\"...\" class=\"figure-img img-fluid\"><figcaption class=\"figure-caption\">A caption.</figcaption></figure>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(878, 'Bootstrap 5: Tables Variant Colors', 'Frontend', 1, 0.00, 'การเปลี่ยนสีแถวหรือเซลล์ในตารางตามสถานะ', 'ไฮไลต์แถวข้อมูลที่สำคัญด้วยสีต่างๆ', '<tr class=\"table-primary\">...</tr>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(879, 'Bootstrap 5: Tables Responsive Wrapper', 'Frontend', 1, 0.00, 'การทำตารางให้มีแถบเลื่อนบนมือถือ (table-responsive)', 'ป้องกันตารางล้นหน้าจอบนอุปกรณ์ขนาดเล็ก', '<div class=\"table-responsive\"><table class=\"table\">...</table></div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(880, 'Bootstrap 5: Border Radius Variations', 'Frontend', 1, 0.00, 'การปรับความโค้งมนมุมกล่อง (rounded-pill, rounded-circle)', 'ทำปุ่มแคปซูลเม็ดยาหรือกรอบรูปวงกลม', '<button class=\"btn btn-primary rounded-pill\">Pill button</button>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(881, 'Bootstrap 5: Clearfix Utility', 'Frontend', 1, 0.00, 'การเคลียร์สถานะลอยตัวของเลย์เอาต์ (clearfix)', 'แก้ปัญหาคอนเทนต์ลอยทะลุกรอบแม่', '<div class=\"clearfix\">...</div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(882, 'Bootstrap 5: Ratio Custom Aspect', 'Frontend', 1, 0.00, 'การปรับสัดส่วนเฟรมเฉพาะตัว (ratio-4x3, ratio-21x9)', 'กำหนดขนาดสัดส่วนพื้นที่แสดงผลสื่อวิดีโอ', '<div class=\"ratio ratio-4x3\"><iframe src=\"...\"></iframe></div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(883, 'Bootstrap 5: Visually Hidden Focusable', 'Frontend', 1, 0.00, 'ซ่อนข้อความแต่จะแสดงขึ้นมาเมื่อถูกโฟกัสด้วยคีย์บอร์ด', 'ช่วยให้ผู้ใช้งานผ่านคีย์บอร์ดใช้งานเว็บไซต์ได้สะดวก', '<a class=\"visually-hidden-focusable\" href=\"#content\">Skip to main content</a>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(884, 'Bootstrap 5: Link Opacity Utilities', 'Frontend', 1, 0.00, 'การปรับความโปร่งแสงของลิงก์ข้อความ (link-opacity)', 'กำหนดความจางของลิงก์เพื่อความสวยงาม', '<a class=\"link-opacity-50\" href=\"#\">Link opacity</a>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(885, 'Bootstrap 5: Card Text Links and Overlays', 'Frontend', 1, 0.00, 'การวางลิงก์ทับหรือซ้อนภาพในการ์ดคอมโพเนนต์', 'ทำลิงก์ครอบคลุมพื้นที่การ์ดทั้งหมด', '<a href=\"#\" class=\"stretched-link\">Go somewhere</a>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
(886, 'Bootstrap 5: Accordion Flush Flush', 'Frontend', 1, 0.00, 'การทำกล่องพับข้อความแบบไร้เส้นขอบนอก (accordion-flush)', 'ออกแบบกล่องคำถามให้แนบสนิทไปกับเลย์เอาต์หลัก', '<div class=\"accordion accordion-flush\" id=\"accordionFlushExample\">...</div>', '2026-08-21 13:15:39', '2026-08-21 13:15:39'),
