(972, 'Bootstrap 5: Rounded Corner Variations', 'Frontend', 1, 0.00, 'การเลือกมุมโค้งมนเฉพาะจุด (rounded-top, rounded-start)', 'กำหนดให้โค้งมนเฉพาะมุมบนหรือด้านซ้าย', '<img src=\"...\" class=\"rounded-top\" alt=\"...\">', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(973, 'Bootstrap 5: Font Size Utility Scale', 'Frontend', 1, 0.00, 'การกำหนดขนาดตัวอักษรสำเร็จรูป (fs-1 ถึง fs-6)', 'ปรับขนาดข้อความมาตรฐานโดยไม่ต้องเขียน CSS เอง', '<p class=\"fs-4\">Medium-large text</p>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(974, 'Bootstrap 5: Font Style Italic Utility', 'Frontend', 1, 0.00, 'การทำตัวหนังสือเอียงด้วยคลาสสำเร็จรูป', 'เน้นข้อความคำพูดหรือชื่ออ้างอิง', '<p class=\"fst-italic\">Italicized text</p>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(975, 'Bootstrap 5: Text Decoration Classes', 'Frontend', 1, 0.00, 'การจัดการเส้นใต้หรือขีดฆ่าข้อความ (text-decoration-*)', 'ลบเส้นใต้ลิงก์หรือเพิ่มเส้นขีดฆ่าราคาสินค้า', '<a href=\"#\" class=\"text-decoration-none\">No underline link</a>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(976, 'Bootstrap 5: Text Transform Uppercase', 'Frontend', 1, 0.00, 'การบังคับแสดงผลตัวพิมพ์ใหญ่ทั้งหมด', 'ใช้กับหัวข้อหมวดหมู่หรือป้ายกำกับ', '<span class=\"text-uppercase\">category name</span>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(977, 'Bootstrap 5: Font Monospace Utility', 'Frontend', 1, 0.00, 'การเปลี่ยนฟอนต์เป็นแบบความกว้างเท่ากัน (font-monospace)', 'ใช้แสดงผลชุดโค้ดโปรแกรมหรือคีย์ API', '<p class=\"font-monospace\">API_KEY = \"123456\"</p>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(978, 'Bootstrap 5: Vertical Rule Separator', 'Frontend', 1, 0.00, 'การสร้างเส้นคั่นแนวตั้ง (vr)', 'ใช้คั่นเมนูหรือไอเทมในแนวนอน', '<div class=\"d-flex\" style=\"height: 50px;\"><div class=\"p-2\">Flex item</div><div class=\"vr\"></div><div class=\"p-2\">Flex item</div></div>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(979, 'Bootstrap 5: Colored Links Hover States', 'Frontend', 1, 0.00, 'การเปลี่ยนสีลิงก์เมื่อเอาเมาส์ชี้ (link-dark, link-light)', 'ควบคุมลูกเล่นสีของลิงก์ข้อความ', '<a href=\"#\" class=\"link-secondary link-offset-2 link-underline-opacity-25 link-underline-opacity-100-hover\">Interactive link</a>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(980, 'Bootstrap 5: Table Group Dividers', 'Frontend', 1, 0.00, 'การสร้างเส้นคั่นหนาพิเศษระหว่างส่วนหัวและเนื้อหาตาราง', 'จัดระเบียบตารางข้อมูลให้ดูแยกส่วนชัดเจน', '<tbody class=\"table-group-divider\"><tr>...</tr></tbody>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(981, 'Bootstrap 5: Table Small Compact', 'Frontend', 1, 0.00, 'การย่อขนาดตารางให้กระชับ (table-sm)', 'ลดระยะห่างในเซลล์ตารางเพื่อแสดงข้อมูลได้เยอะขึ้น', '<table class=\"table table-sm\">...</table>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(982, 'Bootstrap 5: Image Thumbnail Style', 'Frontend', 1, 0.00, 'การทำกรอบรูปถ่ายสไตล์โพลารอยด์ (img-thumbnail)', 'ใส่กรอบขาวและมุมโค้งให้รูปภาพตัวอย่าง', '<img src=\"...\" class=\"img-thumbnail\" alt=\"...\">', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(983, 'Bootstrap 5: Figures Alignment Classes', 'Frontend', 1, 0.00, 'การจัดตำแหน่งรูปภาพพร้อมคำบรรยายให้อยู่กลาง', 'จัดระเบียบรูปภาพและแคปชันประกอบบทความ', '<figure class=\"figure text-center\"><img src=\"...\" class=\"figure-img img-fluid rounded\"><figcaption class=\"figure-caption\">Caption</figcaption></figure>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(984, 'Bootstrap 5: Badge Position Absolute', 'Frontend', 1, 0.00, 'การวางป้ายแจ้งเตือนลอยทับไอคอน (position-absolute)', 'ทำป้ายบอกจำนวนข้อความใหม่บนไอคอนกระดิ่ง', '<button type=\"button\" class=\"btn btn-primary position-relative\">Inbox <span class=\"position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger\">+99</span></button>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(985, 'Bootstrap 5: Alert Link Styling', 'Frontend', 1, 0.00, 'การใส่ลิงก์ภายในกล่องแจ้งเตือน (alert-link)', 'จัดรูปแบบสีลิงก์ให้อ่านง่ายเข้ากับกล่อง Alert', '<div class=\"alert alert-primary\" role=\"alert\">A simple alert—check out <a href=\"#\" class=\"alert-link\">this link</a>.</div>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(986, 'Bootstrap 5: Progress Bar Multiple Bars', 'Frontend', 1, 0.00, 'การรวมแถบความคืบหน้าหลายสีในแท่งเดียว', 'แสดงสัดส่วนข้อมูลหลายประเภทรวมกัน', '<div class=\"progress\" role=\"progressbar\"><div class=\"progress-bar bg-success\" style=\"width: 15%\"></div><div class=\"progress-bar bg-warning\" style=\"width: 30%\"></div></div>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(987, 'Bootstrap 5: List Group Interactive Items', 'Frontend', 1, 0.00, 'การทำรายการลิสต์ให้กดคลิกโต้ตอบได้ (list-group-item-action)', 'ทำเมนูเลือกรายการที่มีเอฟเฟกต์เปลี่ยนสีตอนเอาเมาส์ชี้', '<div class=\"list-group\"><a href=\"#\" class=\"list-group-item list-group-item-action active\">Link item</a></div>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(988, 'Bootstrap 5: List Group Colored Variants', 'Frontend', 1, 0.00, 'การเปลี่ยนสีแถวรายการลิสต์ตามสถานะ', 'ไฮไลต์รายการที่สำคัญด้วยสีต่างๆ', '<ul class=\"list-group\"><li class=\"list-group-item list-group-item-primary\">A simple primary list group item</li></ul>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(989, 'Bootstrap 5: Card Header Tabs Integration', 'Frontend', 1, 0.00, 'การใส่แท็บสลับหน้าจอไว้ที่ส่วนหัวของการ์ด', 'ทำกล่องคอนเทนต์ที่มีเมนูสลับมุมมองด้านบน', '<div class=\"card text-center\"><div class=\"card-header\"><ul class=\"nav nav-tabs card-header-tabs\"><li class=\"nav-item\"><a class=\"nav-link active\" href=\"#\">Active</a></li></ul></div></div>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(990, 'Bootstrap 5: Accordion Always Open', 'Frontend', 1, 0.00, 'เปิดใช้งานกล่องพับให้กางออกพร้อมกันได้หลายอัน', 'ยกเลิกเงื่อนไขการพับอันเก่าเมื่อกดเปิดอันใหม่', '<div class=\"accordion\" id=\"accordionPanelsStayOpenExample\">...', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(991, 'Bootstrap 5: Carousel Dark Variant Controls', 'Frontend', 1, 0.00, 'ปรับปุ่มกดสไลเดอร์รูปภาพให้เป็นสีเข้ม', 'ใช้กับภาพพื้นหลังสไลด์สีขาวเพื่อให้มองเห็นปุ่มกดชัดเจน', '<div id=\"carouselExampleDark\" class=\"carousel carousel-dark slide\">...', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(992, 'Bootstrap 5: Close Button Disabled State', 'Frontend', 1, 0.00, 'การปิดใช้งานปุ่มกากบาทชั่วคราว (disabled)', 'ป้องกันไม่ให้ผู้ใช้กดปิดปุ่ม', '<button type=\"button\" class=\"btn-close\" disabled aria-label=\"Close\"></button>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(993, 'Bootstrap 5: Dropdown Menu End Alignment', 'Frontend', 1, 0.00, 'การจัดดรอปดาวน์เมนูให้ชิดขวา (dropdown-menu-end)', 'ป้องกันไม่ให้เมนูล้นออกนอกขอบจอทางขวา', '<div class=\"dropdown-menu dropdown-menu-end\">...', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(994, 'Bootstrap 5: Navbar Text Center Brand', 'Frontend', 1, 0.00, 'การจัดวางแบรนด์หรือโลโก้อไว้ตรงกลาง Navbar', 'ทำดีไซน์เมนูด้านบนสไตล์โมเดิร์น', '<nav class=\"navbar navbar-expand-lg bg-body-tertiary\"><div class=\"container-fluid justify-content-center\"><a class=\"navbar-brand\" href=\"#\">Navbar</a></div></nav>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(995, 'Bootstrap 5: Nav Pills Variant', 'Frontend', 1, 0.00, 'การทำเมนูแท็บแบบปุ่มแคปซูล (nav-pills)', 'ทางเลือกดีไซน์แท็บสลับหน้าจอแบบเม็ดแคปซูลโค้งมน', '<ul class=\"nav nav-pills\"><li class=\"nav-item\"><a class=\"nav-link active\" href=\"#\">Active</a></li></ul>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(996, 'Bootstrap 5: Nav Fill and Justified', 'Frontend', 1, 0.00, 'การขยายเมนูแท็บให้เต็มความกว้างพื้นที่ (nav-fill)', 'จัดสรรปุ่มเมนูด้านบนให้กระจายเต็มจอเท่าๆ กัน', '<ul class=\"nav nav-pills nav-fill\"><li class=\"nav-item\"><a class=\"nav-link active\" href=\"#\">Active</a></li></ul>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(997, 'Bootstrap 5: Offcanvas Top and Bottom', 'Frontend', 1, 0.00, 'การตั้งค่าเปิดแถบ Offcanvas จากด้านบนหรือล่างจอ', 'ทำแถบแจ้งเตือนหรือเมนูเลื่อนลงมาจากหัวจอ', '<div class=\"offcanvas offcanvas-top\" tabindex=\"-1\" id=\"offcanvasTop\">...', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(998, 'Bootstrap 5: Pagination Alignment Center', 'Frontend', 1, 0.00, 'การจัดตำแหน่งปุ่มเปลี่ยนหน้าตารางให้อยู่กึ่งกลาง', 'จัดหน้าตาปุ่มเลขหน้าให้อยู่กลางหน้าจอ', '<nav aria-label=\"Page navigation\"><ul class=\"pagination justify-content-center\"><li class=\"page-item\"><a class=\"page-link\" href=\"#\">Previous</a></li></ul></nav>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(999, 'Bootstrap 5: Placeholders Animation Glow', 'Frontend', 1, 0.00, 'เอฟเฟกต์กระพริบเรืองแสงให้ส켈เลตอนโหลด (placeholder-glow)', 'เพิ่มลูกเล่นการโหลดข้อมูลให้ดูไหลลื่นสมจริง', '<p class=\"placeholder-glow\"><span class=\"placeholder col-7\"></span></p>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1000, 'Bootstrap 5: Popover Container Body', 'Frontend', 1, 0.00, 'การกำหนดให้ Popover แสดงผลเทียบกับบอดี้หลัก', 'แก้ปัญหาการแสดงผลกรอบทับซ้อนกับ overflow ของคอนเทนต์', '<button type=\"button\" class=\"btn btn-secondary\" data-bs-toggle=\"popover\" data-bs-container=\"body\">Popover</button>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1001, 'Bootstrap 5: Spinner Small Variant', 'Frontend', 1, 0.00, 'การย่อขนาดไอคอนโหลดให้เล็กจิ๋ว (spinner-border-sm)', 'วางไอคอนโหลดแทรกไว้ข้างในปุ่มกดเวลาคลิกส่งข้อมูล', '<button class=\"btn btn-primary\" type=\"button\" disabled><span class=\"spinner-border spinner-border-sm\" aria-hidden=\"true\"></span><span role=\"status\">Loading...</span></button>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1002, 'Bootstrap 5: Form Control Plaintext', 'Frontend', 1, 0.00, 'การแสดงผลฟอร์มแบบข้อความธรรมดา (form-control-plaintext)', 'ใช้แสดงข้อมูลที่อ่านได้อย่างเดียวแต่ยังคงจัดฟอร์มตรงกัน', '<input type=\"text\" readonly class=\"form-control-plaintext\" value=\"email@example.com\">', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1003, 'Bootstrap 5: Form Text Help Block', 'Frontend', 1, 0.00, 'การใส่ข้อความช่วยเหลือใต้ช่องกรอกข้อมูล (form-text)', 'อธิบายเงื่อนไขการกรอกข้อมูลเช่น ต้องมีความยาวอย่างน้อย 8 ตัวอักษร', '<div id=\"passwordHelpBlock\" class=\"form-text\">Your password must be 8-20 characters long.</div>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1004, 'Bootstrap 5: Input Group Multiple Inputs', 'Frontend', 1, 0.00, 'การรวมช่องกรอกข้อมูลหลายช่องไว้ในบรรทัดเดียว', 'ทำฟอร์มกรอกชื่อและนามสกุลติดกัน', '<div class=\"input-group\"><span class=\"input-group-text\">First and last name</span><input type=\"text\" class=\"form-control\"><input type=\"text\" class=\"form-control\"></div>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1005, 'Bootstrap 5: Validation Server Side', 'Frontend', 1, 0.00, 'การแสดงผลสถานะตรวจสอบข้อมูลจากฝั่งเซิร์ฟเวอร์', 'ใส่คลาส is-valid หรือ is-is-invalid เพื่อแสดงผลลัพธ์การตรวจสอบ', '<input class=\"form-control is-invalid\" id=\"validationServer01\" value=\"Mark\" required>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1006, 'Bootstrap 5: Checks Switches Toggle', 'Frontend', 1, 0.00, 'การทำสวิตช์เปิด-ปิดสไตล์ไอโฟน (form-switch)', 'ทางเลือกเสริมแทนปุ่มติ๊ก Checkbox แบบเดิม', '<div class=\"form-check form-switch\"><input class=\"form-check-input\" type=\"checkbox\" role=\"switch\" id=\"flexSwitchCheckDefault\"></div>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1007, 'Bootstrap 5: Range Sizing Custom', 'Frontend', 1, 0.00, 'การปรับแต่งแถบสไลด์เลื่อนค่าตัวเลข', 'กำหนดค่าสเกลเริ่มต้นและสิ้นสุดของแถบเลื่อน', '<input type=\"range\" class=\"form-range\" min=\"0\" max=\"5\" step=\"0.5\" id=\"customRange3\">', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1008, 'Bootstrap 5: Floating Labels Textarea', 'Frontend', 1, 0.00, 'ป้ายชื่อลอยตัวสำหรับช่องข้อความขนาดใหญ่ (textarea)', 'ทำกล่องแสดงความคิดเห็นพร้อมป้ายชื่อขยับอัตโนมัติ', '<div class=\"form-floating\"><textarea class=\"form-control\" placeholder=\"Leave a comment here\" id=\"floatingTextarea2\" style=\"height: 100px\"></textarea><label for=\"floatingTextarea2\">Comments</label></div>', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1009, 'Bootstrap 5: Navbar Expand Responsive Breakpoint', 'Frontend', 1, 0.00, 'การกำหนดจุดขยายพับเมนูของ Navbar (navbar-expand-lg)', 'ควบคุมว่าให้แถบเมนูปรากฏเต็มจอหรือพับเป็นแฮมเบอร์เกอร์ที่ขนาดจอไหน', '<nav class=\"navbar navbar-expand-lg bg-body-tertiary\">...', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1010, 'Bootstrap 5: Modal Custom Animation Fade', 'Frontend', 1, 0.00, 'การเปิดปิดเอฟเฟกต์เฟดอนิเมชันของหน้าต่างโมดอล', 'ทำให้ป๊อปอัพค่อยๆ ปรากฏขึ้นมาอย่างนุ่มนวล', '<div class=\"modal fade\" id=\"exampleModal\" tabindex=\"-1\">...', '2026-08-21 13:16:40', '2026-08-21 13:16:40'),
(1011, 'Bootstrap 5: Color Modes API Data Attribute', 'Frontend', 1, 0.00, 'การสลับโหมดสีสว่างและมืดผ่านแอตทริบิวต์ data-bs-theme', 'ใช้กำหนดค่าสีธีมให้คอมโพเนนต์หรือทั้งหน้าเว็บ (light / dark)', '<div data-bs-theme=\"dark\">...</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1012, 'Bootstrap 5: CSS Variables Customization', 'Frontend', 1, 0.00, 'การปรับแต่งค่าตัวแปร CSS ของ Bootstrap (CSS Custom Properties)', 'ใช้overrideค่าสีหรือฟอนต์โดยตรงผ่านสไตล์อินไลน์หรือไฟล์ CSS', ':root { --bs-primary: #ff5733; }', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1013, 'Bootstrap 5: Sass Color System Customization', 'Frontend', 1, 0.00, 'การปรับแต่งชุดสีหลักผ่านตัวแปร Sass', 'แก้ไขไฟล์ Sass variable ก่อนคอมไพล์เพื่อเปลี่ยนธีมระบบ', '$primary: #6f42c1;', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1014, 'Bootstrap 5: Utility API Customization', 'Frontend', 1, 0.00, 'การเพิ่มหรือแก้ไขคลาส Utility ด้วย Sass Utility API', 'สร้างคลาสคำสั่งเสริมเฉพาะตัวโปรเจกต์ผ่านฟังก์ชัน Sass', '$utilities: map-merge(...)', '2026-08-21 13:20:21', '2026-08-21 13:20:21');
INSERT INTO `component_items` (`id`, `name`, `category`, `stock`, `price`, `description`, `how_to_use`, `snippet`, `created_at`, `updated_at`) VALUES
(1015, 'Bootstrap 5: RTL Text Direction Support', 'Frontend', 1, 0.00, 'การรองรับการแสดงผลภาษาที่อ่านจากขวาไปซ้าย (RTL)', 'กำหนดแอตทริบิวต์ที่แท็ก html สำหรับภาษาอาหรับหรือฮีบรู', '<html lang=\"ar\" dir=\"rtl\">', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1016, 'Bootstrap 5: Print Visibility Utility Classes', 'Frontend', 1, 0.00, 'การควบคุมการแสดงผลเมื่อสั่งพิมพ์เอกสารกระดาษ (d-print-*)', 'ซ่อนหรือแสดงคอนเทนต์เฉพาะตอนสั่ง Print หน้าเว็บ', '<div class=\"d-print-none\">Do not print this</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1017, 'Bootstrap 5: Responsive Font Sizes (RFS)', 'Frontend', 1, 0.00, 'การเปิดใช้งานระบบปรับขนาดฟอนต์อัตโนมัติ', 'ช่วยให้ตัวหนังสือขยายหรือย่อขนาดสมดุลตามหน้าจอ', '$enable-rfs: true;', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1018, 'Bootstrap 5: Border Width Customization', 'Frontend', 1, 0.00, 'การกำหนดความหนาของเส้นขอบ (border-1 ถึง border-5)', 'ปรับขนาดความหนาเส้นกรอบการ์ดหรือตาราง', '<div class=\"border border-3\">Thicker border</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1019, 'Bootstrap 5: Opacity CSS Variables Override', 'Frontend', 1, 0.00, 'การควบคุมความโปร่งแสงผ่านตัวแปรซอส', 'กำหนดค่าเปอร์เซ็นต์ความจางของคอมโพเนนต์', 'style=\"--bs-bg-opacity: .5;\"', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1020, 'Bootstrap 5: Box Shadow Custom Variables', 'Frontend', 1, 0.00, 'การปรับแต่งเงากล่องด้วยตัวแปร CSS', 'เปลี่ยนความเข้มและระยะเงาของการ์ดหรือปุ่ม', 'style=\"--bs-box-shadow: 0 0.5rem 1rem rgba(0,0,0,.15);\"', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1021, 'Bootstrap 5: Stack Vertical Layout Helper', 'Frontend', 1, 0.00, 'การจัดเลย์เอาต์แนวตั้งด่วนด้วยคลาส vstack', 'จัดระเบียบไอเทมเรียงต่อกันลงมาด้านล่างพร้อมเว้นระยะห่าง', '<div class=\"vstack gap-2\"><div>First</div><div>Second</div></div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1022, 'Bootstrap 5: HStack Horizontal Layout Helper', 'Frontend', 1, 0.00, 'การจัดเลย์เอาต์แนวนอนด่วนด้วยคลาส hstack', 'จัดเรียงไอเทมในแนวนอนพร้อมดันซ้ายขวาอัตโนมัติ', '<div class=\"hstack gap-3\"><div class=\"p-2\">First</div><div class=\"p-2 ms-auto\">Right</div></div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1023, 'Bootstrap 5: Link Hover Styling Utilities', 'Frontend', 1, 0.00, 'การควบคุมลูกเล่นสีลิงก์เมื่อเอาเมาส์ชี้', 'กำหนดเอฟเฟกต์เส้นใต้หรือเปลี่ยนสีลิงก์', '<a href=\"#\" class=\"link-dark link-offset-2 link-underline-opacity-25 link-underline-opacity-100-hover\">Link</a>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1024, 'Bootstrap 5: Stretched Link Multiple Cards', 'Frontend', 1, 0.00, 'การทำลิงก์ครอบคลุมพื้นที่การ์ดทั้งหมด', 'ทำให้คลิกพื้นที่ไหนในการ์ดก็ลิงก์ไปหน้าเป้าหมายได้', '<a href=\"#\" class=\"stretched-link\">Card link</a>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1025, 'Bootstrap 5: Ratio Custom Media Embedder', 'Frontend', 1, 0.00, 'การกำหนดสัดส่วนหน้าจอสื่อวิดีโอแบบระบุค่าเอง', 'ทำกรอบวิดีโอสัดส่วนพิเศษนอกเหนือจาก 16:9', '<div class=\"ratio\" style=\"--bs-aspect-ratio: 50%;\">...</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1026, 'Bootstrap 5: Position Sticky Offsets', 'Frontend', 1, 0.00, 'การกำหนดระยะห่างตำแหน่งตรึงหน้าจอ (sticky-top)', 'กำหนดว่าให้ตรึงติดขอบบนห่างลงมาเท่าไหร่', '<div class=\"sticky-top\" style=\"top: 50px;\">Sticky with offset</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1027, 'Bootstrap 5: Flex Wrap Reverse Utilities', 'Frontend', 1, 0.00, 'การสลับทิศทางการปัดตกบรรทัดของ Flexbox (flex-wrap-reverse)', 'จัดลำดับการตัดบรรทัดย้อนกลับ', '<div class=\"d-flex flex-wrap-reverse\">...</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1028, 'Bootstrap 5: Flex Grow and Shrink Control', 'Frontend', 1, 0.00, 'การควบคุมการขยายและหดตัวของไอเทม (flex-grow-1, flex-shrink-0)', 'บังคับให้ไอเทมขยายเต็มพื้นที่หรือห้ามหดตัว', '<div class=\"flex-grow-1\">Flex grow</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1029, 'Bootstrap 5: Justify Content Around Between Evenly', 'Frontend', 1, 0.00, 'การกระจายช่องว่างระหว่างไอเทมในแนวนอน', 'จัดวางตำแหน่งไอเทมให้มีช่องว่างรอบตัวหรือระหว่างกันเท่าๆ กัน', '<div class=\"d-flex justify-content-evenly\">...</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1030, 'Bootstrap 5: Align Content Multi-row Flex', 'Frontend', 1, 0.00, 'การจัดตำแหน่งแถวในระบบ Flexbox หลายบรรทัด (align-content-*)', 'ควบคุมระยะห่างของแถวข้อมูลเมื่อมีการปัดตกบรรทัด', '<div class=\"d-flex flex-wrap align-content-between\">...</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1031, 'Bootstrap 5: Order First and Last Grid Utilities', 'Frontend', 1, 0.00, 'การบังคับให้คอลัมน์แสดงผลเป็นตัวแรกหรือตัวสุดท้าย', 'สลับตำแหน่งจัดวางคอลัมน์บนมือถือกับคอมพิวเตอร์', '<div class=\"col order-first\">First</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1032, 'Bootstrap 5: Offset Grid Column Resetting', 'Frontend', 1, 0.00, 'การยกเลิกช่องว่างที่เคยเว้นไว้ในขนาดจอก่อนหน้า (offset-md-0)', 'ล้างค่าการเยื้องคอลัมน์ในขนาดจอที่กำหนด', '<div class=\"col-md-6 offset-md-3 offset-lg-0\">Reset offset</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1033, 'Bootstrap 5: Table Custom Border Styles', 'Frontend', 1, 0.00, 'การเปลี่ยนรูปแบบเส้นขอบตาราง (table-bordered, table-borderless)', 'เปิดหรือปิดเส้นตารางตามความต้องการดีไซน์', '<table class=\"table table-bordered\">...</table>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1034, 'Bootstrap 5: Table Active and Hover States', 'Frontend', 1, 0.00, 'การไฮไลต์แถวตารางเมื่อเอาเมาส์ชี้หรือเลือก', 'เน้นแถวข้อมูลที่กำลังสนใจ', '<tr class=\"table-active\">...</tr>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1035, 'Bootstrap 5: Table Caption Placement Top', 'Frontend', 1, 0.00, 'การย้ายหัวข้อคำอธิบายตารางไปไว้ด้านบน', 'กำหนดตำแหน่งข้อความอธิบายตาราง', '<table class=\"table caption-top\"><caption>List of users</caption>...</table>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1036, 'Bootstrap 5: Figure Caption Styling Custom', 'Frontend', 1, 0.00, 'การตกแต่งข้อความใต้ภาพประกอบบทความ', 'จัดสีหรือขนาดฟอนต์ของคำอธิบายภาพ', '<figcaption class=\"figure-caption text-end\">A caption for the above image.</figcaption>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1037, 'Bootstrap 5: Image Thumbnail Customization', 'Frontend', 1, 0.00, 'การปรับแต่งกรอบรูปโพลารอยด์ผ่านคลาสเสริม', 'เพิ่มความสวยงามให้รูปตัวอย่างสินค้า', '<img src=\"...\" class=\"img-thumbnail rounded-pill\">', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1038, 'Bootstrap 5: Badge Subtractive Variant Colors', 'Frontend', 1, 0.00, 'การใช้ป้ายสัญลักษณ์สีโทนอ่อน (bg-primary-subtle)', 'ทำป้ายสถานะแบบละมุนตาเข้ากับธีมสมัยใหม่', '<span class=\"badge bg-primary-subtle text-primary-emphasis\">Primary subtle</span>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1039, 'Bootstrap 5: Alert Subtractive Variant Colors', 'Frontend', 1, 0.00, 'การใช้กล่องแจ้งเตือนสีโทนอ่อน (alert-primary-subtle)', 'ทำกล่องข้อความเตือนแบบสบายตา', '<div class=\"alert alert-success-subtle text-success-emphasis\">Success alert</div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1040, 'Bootstrap 5: Progress Bar Striped Animation', 'Frontend', 1, 0.00, 'การทำแถบความคืบหน้าแบบมีลายทางวิ่งเคลื่อนไหว', 'เพิ่มลูกเล่นการโหลดข้อมูลให้ดูน่าสนใจ', '<div class=\"progress\"><div class=\"progress-bar progress-bar-striped progress-bar-animated\" style=\"width: 75%\"></div></div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1041, 'Bootstrap 5: List Group Active and Disabled Items', 'Frontend', 1, 0.00, 'การกำหนดสถานะเลือกใช้งานหรือปิดใช้งานในลิสต์', 'ล็อกรายการเมนูไม่ให้กดคลิกได้', '<ul class=\"list-group\"><li class=\"list-group-item disabled\">Disabled item</li></ul>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1042, 'Bootstrap 5: Card Background Overlays and Text Colors', 'Frontend', 1, 0.00, 'การวางข้อความทับบนพื้นหลังการ์ดสีเข้ม', 'ทำภาพแบนเนอร์การ์ดพร้อมข้อความสีขาวอ่านง่าย', '<div class=\"card text-bg-dark\"><img src=\"...\" class=\"card-img\" alt=\"...\"><div class=\"card-img-overlay\"><h5 class=\"card-title\">Card title</h5></div></div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1043, 'Bootstrap 5: Accordion Item Collapse Customizations', 'Frontend', 1, 0.00, 'การปรับแต่งกล่องพับข้อความด้วยโค้ดเสริม', 'ควบคุมสถานะการเปิดปิดกล่อง FAQ', '<div class=\"accordion-collapse collapse show\">...', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1044, 'Bootstrap 5: Carousel Crossfade Transition Effect', 'Frontend', 1, 0.00, 'การทำสไลเดอร์รูปภาพแบบค่อยๆ เฟดเปลี่ยนภาพ', 'เปลี่ยนเอฟเฟกต์การเลื่อนภาพจากสไลด์เป็นเฟดนุ่มนวล', '<div id=\"carouselExampleFade\" class=\"carousel slide carousel-fade\">...', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1045, 'Bootstrap 5: Dropdown Menu Item Text and Headers', 'Frontend', 1, 0.00, 'การใส่ข้อความธรรมดาหรือหัวข้อในดรอปดาวน์', 'จัดระเบียบเมนูตัวเลือกให้มีหมวดหมู่ย่อยชัดเจน', '<h6 class=\"dropdown-header\">Dropdown header</h6><p class=\"dropdown-item-text\">Text in dropdown</p>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1046, 'Bootstrap 5: Modal Custom Event Listeners JS', 'Frontend', 1, 0.00, 'การดักจับอีเวนต์ JavaScript ของโมเดลตอนเปิดปิด', 'เขียนโค้ดสั่งการทำงานเมื่อป๊อปอัพเด้งขึ้นมา', 'const myModalEl = document.getElementById(\'myModal\'); myModalEl.addEventListener(\'show.bs.modal\', event => { ... })', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1047, 'Bootstrap 5: Offcanvas Custom Events JS', 'Frontend', 1, 0.00, 'การดักจับอีเวนต์เปิดปิดของแถบ Offcanvas', 'ควบคุมการทำงานเมื่อเมนูด้านข้างสไลด์เข้ามา', 'const myOffcanvas = document.getElementById(\'offcanvas\'); myOffcanvas.addEventListener(\'shown.bs.offcanvas\', event => { ... })', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1048, 'Bootstrap 5: Tooltip Initialization JavaScript', 'Frontend', 1, 0.00, 'การเรียกใช้งาน Tooltip ผ่าน JavaScript', 'เปิดใช้งานคำอธิบายตัวช่วยทั่วทั้งหน้าเว็บ', 'const tooltipTriggerList = document.querySelectorAll(\'[data-bs-toggle=\"tooltip\"]\'); const tooltipList = [...tooltipTriggerList].map(tooltipTriggerEl => new bootstrap.Tooltip(tooltipTriggerEl))', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1049, 'Bootstrap 5: Popover Initialization JavaScript', 'Frontend', 1, 0.00, 'การเรียกใช้งาน Popover ผ่าน JavaScript', 'เปิดใช้งานกรอบข้อความแนะนำผ่านคลาสบีเอส', 'const popoverTriggerList = document.querySelectorAll(\'[data-bs-toggle=\"popover\"]\'); const popoverList = [...popoverTriggerList].map(popoverTriggerEl => new bootstrap.Popover(popoverTriggerEl))', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1050, 'Bootstrap 5: Toast Programmatic Trigger JS', 'Frontend', 1, 0.00, 'การสั่งแสดงผลกล่อง Toast ผ่านสคริปต์จาวาสคริปต์', 'เรียกแจ้งเตือนลอยมุมจอเมื่อเกิดเหตุการณ์สำเร็จ', 'const toastElList = document.querySelectorAll(\'.toast\'); const toastList = [...toastElList].map(toastEl => new bootstrap.Toast(toastEl).show())', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1051, 'Bootstrap 5: Form Floating Textarea Auto-height', 'Frontend', 1, 0.00, 'ป้ายชื่อลอยตัวสำหรับช่องข้อความยาว', 'ทำกล่องแสดงความคิดเห็นพร้อมป้ายชื่อขยับอัตโนมัติ', '<div class=\"form-floating\"><textarea class=\"form-control\" placeholder=\"Leave a comment here\" id=\"floatingTextarea\"></textarea><label for=\"floatingTextarea\">Comments</label></div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1052, 'Bootstrap 5: Input Group Multiple Addons Layout', 'Frontend', 1, 0.00, 'การใส่ข้อความประกอบหน้าหลังช่องกรอกข้อมูลหลายตัว', 'ทำฟอร์มรับข้อมูลราคาพร้อมหน่วยเงิน', '<div class=\"input-group\"><span class=\"input-group-text\">$</span><span class=\"input-group-text\">0.00</span><input type=\"text\" class=\"form-control\"></div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1053, 'Bootstrap 5: Form Range Custom Styling Variables', 'Frontend', 1, 0.00, 'การปรับแต่งหน้าตาแถบเลื่อนตัวเลขผ่านตัวแปร CSS', 'เปลี่ยนสีปุ่มสไลด์และแถบรางเลื่อน', 'style=\"--bs-range-track-bg: #dee2e6; --bs-range-thumb-bg: #0d6efd;\"', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1054, 'Bootstrap 5: Validation Custom JavaScript Check', 'Frontend', 1, 0.00, 'การเขียนสคริปต์ตรวจสอบความถูกต้องของฟอร์ม', 'ป้องกันการกดส่งฟอร์มหากข้อมูลยังกรอกไม่ครบถ้วน', '(() => { \'use strict\'; const forms = document.querySelectorAll(\'.needs-validation\'); ... })()', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1055, 'Bootstrap 5: Navbar Collapse JavaScript API', 'Frontend', 1, 0.00, 'การสั่งพับหรือกางเมนู Navbar ผ่าน JavaScript', 'ควบคุมการแสดงผลเมนูแฮมเบอร์เกอร์ผ่านโค้ด', 'const bsCollapse = new bootstrap.Collapse(myCollapse, { toggle: false })', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1056, 'Bootstrap 5: Scrollspy JavaScript Configuration', 'Frontend', 1, 0.00, 'การตั้งค่าระบบ Scrollspy ผ่าน JavaScript', 'กำหนดค่าระยะตรวจจับตำแหน่งหน้าจออัตโนมัติ', 'const scrollSpy = new bootstrap.ScrollSpy(document.body, { target: \'#navbar-example2\' })', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1057, 'Bootstrap 5: Offcanvas Backdrop Toggle JS', 'Frontend', 1, 0.00, 'การเปิดปิดฉากหลังมืดของแถบ Offcanvas', 'ควบคุมฉากหลังผ่านอ็อปชันพารามิเตอร์', 'const bsOffcanvas = new bootstrap.Offcanvas(myOffcanvas, { backdrop: false })', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1058, 'Bootstrap 5: Modal Static Keyboard Options', 'Frontend', 1, 0.00, 'การตั้งค่าโมดอลไม่ให้ปิดเมื่อกดปุ่ม Esc บนคีย์บอร์ด', 'บังคับให้ผู้ใช้ต้องคลิกปุ่มปิดเท่านั้น', '<div class=\"modal\" data-bs-keyboard=\"false\">...', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1059, 'Bootstrap 5: Carousel Interval Autoplay Speed', 'Frontend', 1, 0.00, 'การกำหนดความเร็วเวลาในการเปลี่ยนภาพสไลด์อัตโนมัติ', 'ปรับเวลาช้าเร็วในการเลื่อนแบนเนอร์', '<div id=\"carouselExample\" class=\"carousel slide\" data-bs-ride=\"carousel\" data-bs-interval=\"2000\">...', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1060, 'Bootstrap 5: Alert Dismissible Fade Animation', 'Frontend', 1, 0.00, 'การทำกล่องแจ้งเตือนแบบกดปิดได้พร้อมอนิเมชันจางหาย', 'คลิกปุ่มกากบาทแล้วกล่องข้อความจะค่อยๆ เฟดหายไป', '<div class=\"alert alert-warning alert-dismissible fade show\" role=\"alert\">...<button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"Close\"></button></div>', '2026-08-21 13:20:21', '2026-08-21 13:20:21'),
(1061, 'Bootstrap 5: Flex Grow Zero Utility', 'Frontend', 1, 0.00, 'การบังคับไม่ให้ไอเทมขยายขนาดใน Flexbox (flex-grow-0)', 'ใช้ล็อกขนาดของไอเทมไม่ให้ขยายตามพื้นที่ว่างที่เหลือ', '<div class=\"flex-grow-0\">Fixed width item</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1062, 'Bootstrap 5: Flex Shrink One Utility', 'Frontend', 1, 0.00, 'การอนุญาตให้ไอเทมย่อตัวลงได้เมื่อพื้นที่ไม่พอ (flex-shrink-1)', 'ควบคุมพฤติกรรมการบีบอัดขนาดไอเทมในหน้าจอเล็ก', '<div class=\"flex-shrink-1\">Shrinkable item</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1063, 'Bootstrap 5: Order First Last Utilities', 'Frontend', 1, 0.00, 'การจัดลำดับการแสดงผลชิ้นงานด้วย order-first และ order-last', 'สลับตำแหน่งไอเทมตัวแรกหรือตัวสุดท้ายโดยไม่ต้องย้ายโค้ด HTML', '<div class=\"order-first\">Display first</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1064, 'Bootstrap 5: Grid Column Auto Sizing', 'Frontend', 1, 0.00, 'การทำคอลัมน์ให้ขยายขนาดตามเนื้อหาด้านในอัตโนมัติ (col-auto)', 'ใช้จัดกล่องข้อความหรือปุ่มที่ไม่ต้องการความกว้างเต็มแถว', '<div class=\"col-auto\">Auto-sized column</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1065, 'Bootstrap 5: Responsive Grid Mixins Classes', 'Frontend', 1, 0.00, 'การผสมผสานคลาสกริดหลายขนาดหน้าจอในคอลัมน์เดียว', 'กำหนดสัดส่วนการแสดงผลที่แตกต่างกันในแต่ละอุปกรณ์ (เช่น col-12 col-md-6 col-lg-4)', '<div class=\"col-12 col-md-6 col-lg-4\">Responsive card</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1066, 'Bootstrap 5: Margin Negative Utilities', 'Frontend', 1, 0.00, 'การใช้มาร์จิ้นติดลบเพื่อดึงชิ้นงานเกยทับกัน (n-1 ถึง n-5)', 'ใช้ดึงรูปภาพหรือการ์ดให้ขยับขึ้นไปทับขอบกล่องด้านบน', '<div class=\"mt-n3\">Pulled up box</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1067, 'Bootstrap 5: Padding Zero Utility Classes', 'Frontend', 1, 0.00, 'การลบระยะขอบในออกทั้งหมด (p-0 หรือ px-0 py-0)', 'เคลียร์ช่องว่างภายในคอมโพเนนต์ให้แนบสนิท', '<div class=\"p-0\">Edge-to-edge content</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1068, 'Bootstrap 5: Text Break All Utility', 'Frontend', 1, 0.00, 'การบังคับตัดคำทุกตัวอักษรไม่ให้ล้นขอบ (text-break)', 'ตัดคำยาวพิเศษหรือลิงก์ยาวๆ ให้ขึ้นบรรทัดใหม่ทันที', '<p class=\"text-break\">https://very-long-url-string-example.com/path</p>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1069, 'Bootstrap 5: Font Weight Normal and Light', 'Frontend', 1, 0.00, 'การกำหนดน้ำหนักตัวอักษรบางหรือปกติ (fw-light, fw-normal)', 'ปรับแต่งความหนาบางของข้อความในพารากราฟ', '<p class=\"fw-light\">Light weight paragraph</p>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1070, 'Bootstrap 5: Line Height Base and Sm', 'Frontend', 1, 0.00, 'การควบคุมความสูงของบรรทัดข้อความ (lh-1, lh-sm, lh-base, lh-lg)', 'กำหนดระยะห่างระหว่างบรรทัดให้เหมาะสมกับการอ่าน', '<p class=\"lh-base\">Standard line height text</p>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1071, 'Bootstrap 5: Vertical Alignment Baseline', 'Frontend', 1, 0.00, 'การจัดตำแหน่งแนวตั้งชิดแนวบรรทัดฐาน (align-baseline)', 'จัดระดับความสูงของข้อความหรือไอคอนให้อยู่แนวเดียวกัน', '<span class=\"align-baseline\">Baseline text</span>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1072, 'Bootstrap 5: Vertical Alignment Top Middle Bottom', 'Frontend', 1, 0.00, 'การจัดตำแหน่งแนวตั้งชิดบน กลาง หรือล่าง (align-top, align-middle, align-bottom)', 'ปรับตำแหน่งรูปภาพหรือปุ่มให้ตรงกับข้อความข้างเคียง', '<img src=\"...\" class=\"align-middle\">', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1073, 'Bootstrap 5: Background Gradient Generator', 'Frontend', 1, 0.00, 'การใส่เอฟเฟกต์การไล่ระดับสีให้พื้นหลัง (bg-gradient)', 'เพิ่มมิติความสวยงามให้ปุ่มหรือกล่องการ์ด', '<div class=\"bg-primary bg-gradient text-white p-3\">Gradient box</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1074, 'Bootstrap 5: Border Subtractive Color Variants', 'Frontend', 1, 0.00, 'การใส่สีเส้นขอบแบบโทนพาสเทลอ่อน (border-success-subtle)', 'ทำกรอบกล่องแจ้งเตือนหรือการ์ดแบบละมุนตา', '<div class=\"border border-warning-subtle\">Subtle border box</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1075, 'Bootstrap 5: Rounded Circle Profile Images', 'Frontend', 1, 0.00, 'การทำกรอบรูปภาพให้เป็นวงกลมสมบูรณ์ (rounded-circle)', 'ใช้แสดงรูปโปรไฟล์ผู้ใช้งานในระบบ', '<img src=\"...\" class=\"rounded-circle\" width=\"50\" height=\"50\">', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1076, 'Bootstrap 5: Shadow None Utility', 'Frontend', 1, 0.00, 'การลบเงาของคอมโพเนนต์ออกทั้งหมด (shadow-none)', 'ยกเลิกเอฟเฟกต์เงาเริ่มต้นของการ์ดหรือปุ่ม', '<div class=\"shadow-none p-3 bg-light\">Flat box</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1077, 'Bootstrap 5: Visibility Hidden vs Invisible', 'Frontend', 1, 0.00, 'การซ่อนคอมโพเนนต์โดยคงพื้นที่เดิมไว้ (invisible)', 'ซ่อนการแสดงผลแต่พื้นที่เลย์เอาต์ยังคงอยู่เท่าเดิม', '<div class=\"invisible\">Occupies space but hidden</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1078, 'Bootstrap 5: Stacks Vertical Gap Control', 'Frontend', 1, 0.00, 'การกำหนดระยะห่างระหว่างไอเทมในแนวตั้ง (vstack gap-3)', 'จัดระเบียบกลุ่มคอนเทนต์แนวตั้งให้มีระยะห่างเท่ากัน', '<div class=\"vstack gap-3\"><div>Item 1</div><div>Item 2</div></div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1079, 'Bootstrap 5: HStack Horizontal Auto Margin', 'Frontend', 1, 0.00, 'การจัดเรียงไอเทมแนวนอนพร้อมดันชิดซ้ายขวาอัตโนมัติ (hstack ms-auto)', 'ทำแถบเมนูหัวกระดาษที่มีโลโก้อยู่ซ้ายและปุ่มอยู่ขวา', '<div class=\"hstack gap-3\"><div class=\"p-2\">Left</div><div class=\"p-2 ms-auto\">Right</div></div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1080, 'Bootstrap 5: Table Hover Variant Highlighting', 'Frontend', 1, 0.00, 'การเปิดใช้งานเอฟเฟกต์เปลี่ยนสีแถวตารางเมื่อเอาเมาส์ชี้ (table-hover)', 'ช่วยให้ผู้ใช้มองเห็นแถวข้อมูลที่กำลังเลื่อนดูได้ชัดเจน', '<table class=\"table table-hover\">...</table>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1081, 'Bootstrap 5: Table Striped Rows Styling', 'Frontend', 1, 0.00, 'การทำตารางสีสลับแถวคู่คี่ (table-striped)', 'ช่วยให้อ่านข้อมูลตารางขนาดยาวได้ง่ายขึ้น', '<table class=\"table table-striped\">...</table>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1082, 'Bootstrap 5: Image Fluid Responsive Sizing', 'Frontend', 1, 0.00, 'การปรับขนาดรูปภาพให้ย่อขยายตามกรอบอัตโนมัติ (img-fluid)', 'ป้องกันไม่ให้รูปภาพทะลุกอบการแสดงผลบนมือถือ', '<img src=\"...\" class=\"img-fluid\" alt=\"...\">', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
