(1097, 'Bootstrap 5: Popover HTML Content Support', 'Frontend', 1, 0.00, 'การใส่โค้ด HTML ลงไปในเนื้อหาของ Popover', 'แสดงผลรูปภาพหรือปุ่มกดภายในกรอบข้อความแนะนำ', '<button type=\"button\" data-bs-toggle=\"popover\" data-bs-html=\"true\" title=\"<b>Bold title</b>\">Popover</button>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1098, 'Bootstrap 5: Spinner Border Variant Colors', 'Frontend', 1, 0.00, 'การเปลี่ยนสีไอคอนโหลดวงกลมตามโทนสีระบบ (text-success)', 'กำหนดสีไอคอนสถานะการประมวลผล', '<div class=\"spinner-border text-success\" role=\"status\"></div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1099, 'Bootstrap 5: Form Control Validation States', 'Frontend', 1, 0.00, 'การแสดงผลกรอบสถานะฟอร์มถูกต้องหรือผิดพลาด (is-valid / is-invalid)', 'แจ้งเตือนผู้ใช้ทันทีเมื่อกรอกข้อมูลในฟอร์มไม่ผ่านเงื่อนไข', '<input class=\"form-control is-valid\" type=\"text\" value=\"Correct\">', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1100, 'Bootstrap 5: Form Select Sizing Options', 'Frontend', 1, 0.00, 'การปรับขนาดช่องดรอปดาวน์ฟอร์ม (form-select-sm / form-select-lg)', 'ย่อหรือขยายช่องเลือกตัวเลือกให้เข้ากับเลย์เอาต์', '<select class=\"form-select form-select-lg\">...</select>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1101, 'Bootstrap 5: Input Group Sizing Variants', 'Frontend', 1, 0.00, 'การปรับขนาดช่องกลุ่มอินพุต (input-group-sm / input-group-lg)', 'ขยายหรือย่อขนาดกลุ่มช่องกรอกข้อมูลและปุ่มกด', '<div class=\"input-group input-group-sm\">...</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1102, 'Bootstrap 5: Checks Inline Layout Option', 'Frontend', 1, 0.00, 'การเรียงปุ่มติ๊ก Checkbox หรือ Radio ในแนวนอน (form-check-inline)', 'จัดตัวเลือกหลายข้อให้อยู่ในบรรทัดเดียวกัน', '<div class=\"form-check form-check-inline\"><input class=\"form-check-input\" type=\"checkbox\"></div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1103, 'Bootstrap 5: Range Slider Width Control', 'Frontend', 1, 0.00, 'การควบคุมความกว้างของแถบสไลด์เลื่อนค่าตัวเลข', 'ปรับขนาดความยาวแถบสไลด์ให้พอดีกับช่องแสดงผล', '<input type=\"range\" class=\"form-range w-50\">', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1104, 'Bootstrap 5: Floating Labels Multi-line Support', 'Frontend', 1, 0.00, 'ป้ายชื่อลอยตัวสำหรับช่องข้อความหลายบรรทัด', 'ทำกล่องคอมเมนต์พร้อมป้ายชื่อขยับอัตโนมัติอย่างสมบูรณ์แบบ', '<div class=\"form-floating\"><textarea class=\"form-control\" style=\"height: 100px\"></textarea><label>Comments</label></div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1105, 'Bootstrap 5: Navbar Expand Medium Breakpoint', 'Frontend', 1, 0.00, 'การกำหนดจุดพับเมนูของ Navbar ที่ขนาดจอ Medium (navbar-expand-md)', 'ให้แถบเมนูปรากฏเต็มจอเมื่อหน้าจอใหญ่กว่าแท็บเล็ต', '<nav class=\"navbar navbar-expand-md bg-light\">...</nav>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1106, 'Bootstrap 5: Modal Backdrop Click Dismiss Control', 'Frontend', 1, 0.00, 'การควบคุมการปิดโมดอลเมื่อคลิกพื้นที่ว่างรอบนอก', 'เปิดหรือปิดฟังก์ชันคลิกนอกกรอบเพื่อปิดป๊อปอัพ', '<div class=\"modal\" data-bs-backdrop=\"static\">...', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1107, 'Bootstrap 5: Tooltip Custom Boundary Placement', 'Frontend', 1, 0.00, 'การกำหนดขอบเขตการแสดงผล Tooltip ไม่ให้ตกขอบจอ', 'แก้ปัญหาคำอธิบายลอยทะลุขอบหน้าต่างเบราว์เซอร์', '<button type=\"button\" data-bs-toggle=\"tooltip\" data-bs-boundary=\"window\">Tooltip</button>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1108, 'Bootstrap 5: Toast Translucent Background Opacity', 'Frontend', 1, 0.00, 'การทำกล่องแจ้งเตือนลอยแบบพื้นหลังโปร่งแสง', 'ดีไซน์กล่องแจ้งเตือนสไตล์กระจกฝ้า (Glassmorphism)', '<div class=\"toast bg-white bg-opacity-75\" role=\"alert\">...</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1109, 'Bootstrap 5: Dropdown Item Active Disabled State', 'Frontend', 1, 0.00, 'การกำหนดสถานะเลือกใช้งานหรือปิดใช้งานในดรอปดาวน์ไอเทม', 'ล็อกเมนูย่อยไม่ให้กดคลิกได้ชั่วคราว', '<li><a class=\"dropdown-item disabled\" href=\"#\">Disabled link</a></li>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1110, 'Bootstrap 5: Responsive Display Print Utilities', 'Frontend', 1, 0.00, 'การควบคุมการแสดงผลเฉพาะบนกระดาษพิมพ์ (d-print-block)', 'แสดงข้อความหรือตารางเฉพาะตอนสั่ง Print เอกสารเท่านั้น', '<div class=\"d-print-block\">Print only section</div>', '2026-08-21 13:21:02', '2026-08-21 13:21:02'),
(1111, 'Bootstrap 5: Grid Column Equal Width (col)', 'Frontend', 1, 0.00, 'การสร้างคอลัมน์ขนาดเท่ากันอัตโนมัติทุกช่อง (col)', 'ใช้จัดแถวให้คอลัมน์แบ่งพื้นที่เฉลี่ยเท่ากันโดยไม่ต้องระบุตัวเลข', '<div class=\"row\"><div class=\"col\">1</div><div class=\"col\">2</div><div class=\"col\">3</div></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1112, 'Bootstrap 5: Grid Column Setting One Wide (col-8)', 'Frontend', 1, 0.00, 'การกำหนดสัดส่วนคอลัมน์กว้างพิเศษร่วมกับช่องปกติ', 'จัดเลย์เอาต์หลักกว้างและช่อง Sidebar ด้านข้าง', '<div class=\"row\"><div class=\"col-md-8\">Main</div><div class=\"col-md-4\">Sidebar</div></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1113, 'Bootstrap 5: Grid Nested Rows and Columns', 'Frontend', 1, 0.00, 'การซ้อนแถวและคอลัมน์ย่อยลงไปในคอลัมน์หลัก', 'ใช้จัดโครงสร้างตารางหรือกรอบข้อมูลที่ซับซ้อน', '<div class=\"row\"><div class=\"col-sm-8\"><div class=\"row\"><div class=\"col-6\">Nested</div></div></div></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1114, 'Bootstrap 5: Grid Row Cols Multi-column Shortcut', 'Frontend', 1, 0.00, 'การกำหนดจำนวนคอลัมน์ต่อแถวแบบย่อ (row-cols-*)', 'กำหนดให้ทุกคอลัมน์ในแถวแสดงผลแถวละกี่ชิ้นโดยไม่ต้องใส่ col ทุกอัน', '<div class=\"row row-cols-3\"><div class=\"col\">Item</div><div class=\"col\">Item</div><div class=\"col\">Item</div></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1115, 'Bootstrap 5: Flex Fill Equal Space Items', 'Frontend', 1, 0.00, 'การบังคับให้ไอเทมใน Flex ขยายขนาดกว้างเท่ากัน (flex-fill)', 'จัดเรียงปุ่มหรือกล่องการ์ดให้มีความกว้างเท่ากันทั้งหมดในแถว', '<div class=\"d-flex\"><div class=\"p-2 flex-fill\">Flex fill</div><div class=\"p-2 flex-fill\">Flex fill</div></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1116, 'Bootstrap 5: Flex Grow Remaining Space', 'Frontend', 1, 0.00, 'การบังคับให้ไอเทมขยายพื้นที่ที่เหลือทั้งหมด (flex-grow-1)', 'ใช้ดันช่องค้นหาหรือข้อความให้ขยายเต็มพื้นที่ว่าง', '<div class=\"d-flex\"><div class=\"p-2\">Fixed</div><div class=\"p-2 flex-grow-1\">Expands</div></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1117, 'Bootstrap 5: Flex Shrink Prevent Utility', 'Frontend', 1, 0.00, 'การป้องกันไม่ให้ไอเทมถูกบีบอัดขนาดลง (flex-shrink-0)', 'ล็อกขนาดความกว้างของรูปภาพหรือไอคอนไม่ให้หดตัว', '<div class=\"d-flex\"><div class=\"flex-shrink-0\"><img src=\"...\"></div></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1118, 'Bootstrap 5: Align Content Center Flex Rows', 'Frontend', 1, 0.00, 'การจัดเรียงกลุ่มแถว Flex ให้อยู่กึ่งกลางแนวตั้ง (align-content-center)', 'ใช้จัดระเบียบแถวข้อมูลหลายบรรทัดให้อยู่ตรงกลางพื้นที่', '<div class=\"d-flex flex-wrap align-content-center\" style=\"height: 300px;\">...</div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
