(1146, 'Bootstrap 5: Navbar Brand Custom Image Sizing', 'Frontend', 1, 0.00, 'การกำหนดขนาดรูปภาพโลโก้ใน Navbar', 'ปรับความกว้างและความสูงรูปภาพแบรนด์บนแถบเมนู', '<a class=\"navbar-brand\" href=\"#\"><img src=\"logo.svg\" alt=\"Logo\" width=\"30\" height=\"24\" class=\"d-inline-block align-text-top\"> Bootstrap</a>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1147, 'Bootstrap 5: Nav Links Active State Customization', 'Frontend', 1, 0.00, 'การกำหนดสถานะหน้าเว็บปัจจุบันในเมนู (nav-link active)', 'ไฮไลต์เมนูนำทางหน้าที่กำลังใช้งานอยู่', '<a class=\"nav-link active\" aria-current=\"page\" href=\"#\">Active</a>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1148, 'Bootstrap 5: Offcanvas Header Close Button', 'Frontend', 1, 0.00, 'การใส่ปุ่มปิดที่ส่วนหัวของแถบ Offcanvas', 'สร้างปุ่มกากบาทปิดเมนูด้านข้าง', '<div class=\"offcanvas-header\"><h5 class=\"offcanvas-title\">Offcanvas</h5><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"offcanvas\"></button></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1149, 'Bootstrap 5: Pagination Active and Disabled States', 'Frontend', 1, 0.00, 'การกำหนดสถานะหน้าปัจจุบันและปุ่มปิดใช้งานใน Pagination', 'ทำระบบเปลี่ยนหน้าตารางพร้อมบอกหน้าปัจจุบัน', '<li class=\"page-item active\" aria-current=\"page\"><span class=\"page-link\">1</span></li>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1150, 'Bootstrap 5: Placeholder Sizing Variants (placeholder-lg/sm)', 'Frontend', 1, 0.00, 'การปรับขนาดส켈เลตอนโหลดข้อมูลให้ใหญ่หรือเล็ก', 'จับคู่ขนาดโครงร่างโหลดข้อมูลให้ตรงกับตัวหนังสือจริง', '<span class=\"placeholder col-6 placeholder-lg\"></span>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1151, 'Bootstrap 5: Popover Header and Body Separation', 'Frontend', 1, 0.00, 'การแยกส่วนหัวและเนื้อหาภายใน Popover', 'จัดระเบียบกรอบข้อความแนะนำให้มีหัวข้อชัดเจน', 'data-bs-content=\"And here\'s some amazing content.\"', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1152, 'Bootstrap 5: Spinner Growing Sizing Animation', 'Frontend', 1, 0.00, 'การปรับขนาดไอคอนโหลดแบบขยายเข้าออก', 'ทำไอคอนสถานะโหลดข้อมูลขนาดเล็กหรือใหญ่', '<div class=\"spinner-grow spinner-grow-sm\" role=\"status\"></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1153, 'Bootstrap 5: Toast Header Timestamp Display', 'Frontend', 1, 0.00, 'การแสดงเวลาแจ้งเตือนที่ส่วนหัวของ Toast', 'ระบุเวลาที่เกิดเหตุการณ์แจ้งเตือน', '<small class=\"text-muted\">11 mins ago</small>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1154, 'Bootstrap 5: Tooltip Direction Customization (top/bottom)', 'Frontend', 1, 0.00, 'การกำหนดทิศทางการแสดงผล Tooltip (data-bs-placement)', 'เลือกทิศทางแสดงผลข้อความแนะนำรอบปุ่ม', '<button type=\"button\" class=\"btn btn-secondary\" data-bs-toggle=\"tooltip\" data-bs-placement=\"top\" title=\"Tooltip on top\">Tooltip</button>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1155, 'Bootstrap 5: Form Control Readonly Plaintext Style', 'Frontend', 1, 0.00, 'การแสดงผลฟอร์มแบบอ่านอย่างเดียวไร้กรอบ', 'แสดงข้อมูลผู้ใช้แบบล็อกไม่ให้แก้แต่สะอาดตา', '<input type=\"text\" readonly class=\"form-control-plaintext\" value=\"username@site.com\">', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1156, 'Bootstrap 5: Input Group Text Icon Integration', 'Frontend', 1, 0.00, 'การใส่ไอคอนหรือข้อความสัญลักษณ์ใน Input Group', 'ทำช่องกรอกข้อมูลค้นหาพร้อมไอคอนแว่นขยาย', '<div class=\"input-group\"><span class=\"input-group-text\"><i class=\"bi bi-search\"></i></span><input type=\"text\" class=\"form-control\"></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1157, 'Bootstrap 5: Checks Switches Checkbox Layout', 'Frontend', 1, 0.00, 'การทำปุ่มสวิตช์เปิด-ปิดการตั้งค่าระบบ (form-switch)', 'ดีไซน์ปุ่มเปิดปิดฟังก์ชันทันสมัย', '<div class=\"form-check form-switch\"><input class=\"form-check-input\" type=\"checkbox\" id=\"switch\"></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1158, 'Bootstrap 5: Form File Input Single Multiple', 'Frontend', 1, 0.00, 'การเปิดใช้งานอัปโหลดไฟล์เดี่ยวหรือหลายไฟล์พร้อมกัน', 'รองรับการเลือกไฟล์เอกสารหรือรูปภาพ', '<input class=\"form-control\" type=\"file\" id=\"formFileMultiple\" multiple>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1159, 'Bootstrap 5: Floating Labels Required Indicator', 'Frontend', 1, 0.00, 'การทำป้ายชื่อลอยตัวร่วมกับช่องบังคับกรอกข้อมูล', 'แจ้งเตือนผู้ใช้ให้กรอกข้อมูลสำคัญในฟอร์ม', '<div class=\"form-floating mb-3\"><input type=\"email\" class=\"form-control\" required><label>Email address *</label></div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1160, 'Bootstrap 5: Validation Tooltip Feedback Messages', 'Frontend', 1, 0.00, 'การแสดงผลข้อความเตือนความผิดพลาดแบบกรอบลอย (invalid-tooltip)', 'ซ่อนหรือแสดงข้อความเตือนฟอร์มในรูปแบบป๊อปอัพ', '<div class=\"invalid-tooltip\">Please provide a valid zip.</div>', '2026-08-21 13:21:47', '2026-08-21 13:21:47'),
(1161, 'Bootstrap 5: Display-1 to Display-6 Headings', 'Frontend', 1, 0.00, 'การสร้างหัวข้อขนาดใหญ่พิเศษแบบ Display', 'ใช้ทำข้อความพาดหัวหน้าเว็บไซต์ที่เน้นความโดดเด่น', '<h1 class=\"display-1\">Display 1</h1>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1162, 'Bootstrap 5: Lead Paragraph Styling', 'Frontend', 1, 0.00, 'การทำย่อหน้าบทนำให้ตัวหนังสือใหญ่และอ่านง่าย (lead)', 'เน้นข้อความสรุปหรือประโยคแรกของบทความให้เด่นขึ้น', '<p class=\"lead\">This is a lead paragraph.</p>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1163, 'Bootstrap 5: Small Text and Mark', 'Frontend', 1, 0.00, 'การแสดงผลข้อความขนาดเล็กและข้อความไฮไลต์', 'ใช้ทำหมายเหตุหรือเน้นคำสำคัญในบทความ', '<p><small>Small text</small> <mark>Highlighted</mark></p>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1164, 'Bootstrap 5: Blockquotes Styling', 'Frontend', 1, 0.00, 'การจัดรูปแบบคำพูดอ้างอิงให้มีสไตล์', 'ใช้แสดงข้อความจากผู้พูดหรือที่มาของข้อมูล', '<figure><blockquote class=\"blockquote\"><p>Quote...</p></blockquote></figure>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1165, 'Bootstrap 5: List Unstyled Utilities', 'Frontend', 1, 0.00, 'การเอาสัญลักษณ์จุดหน้าลิสต์ออก (list-unstyled)', 'ใช้จัดระเบียบลิสต์เมนูที่ไม่ต้องการสัญลักษณ์นำหน้า', '<ul class=\"list-unstyled\"><li>Item</li></ul>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1166, 'Bootstrap 5: Table Responsive Vertical Scroll', 'Frontend', 1, 0.00, 'การทำตารางให้เลื่อนแนวตั้งได้เฉพาะส่วน', 'ใช้แสดงผลตารางข้อมูลขนาดยาวในพื้นที่จำกัด', '<div class=\"table-responsive\" style=\"max-height: 300px;\"><table class=\"table\">...</table></div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1167, 'Bootstrap 5: Form Floating Select', 'Frontend', 1, 0.00, 'ดรอปดาวน์ฟอร์มที่มีป้ายชื่อลอยตัว (form-floating)', 'ประหยัดพื้นที่ฟอร์มและสวยงามทันสมัย', '<div class=\"form-floating\"><select class=\"form-select\">...</select><label>Label</label></div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1168, 'Bootstrap 5: Validation Feedback Tooltips', 'Frontend', 1, 0.00, 'ข้อความเตือนความถูกต้องของฟอร์มแบบกรอบลอย', 'แสดงข้อความแจ้งเตือนเมื่อข้อมูลผิดพลาดแบบสวยงาม', '<div class=\"invalid-tooltip\">Error message</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1169, 'Bootstrap 5: Input Group Button Addons', 'Frontend', 1, 0.00, 'การใส่ปุ่มกดไว้หน้าหรือหลังช่องกรอกข้อมูล', 'ใช้ทำช่องค้นหาพร้อมปุ่ม Search ติดกัน', '<div class=\"input-group\"><input class=\"form-control\"><button class=\"btn btn-primary\">Go</button></div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1170, 'Bootstrap 5: Checkbox Toggle Buttons', 'Frontend', 1, 0.00, 'การเปลี่ยน Checkbox ให้กลายเป็นปุ่มกดสไตล์ Toggle', 'ทำชุดเลือกตัวเลือกแบบปุ่มกด (Button Group)', '<input type=\"checkbox\" class=\"btn-check\" id=\"btn\"><label class=\"btn btn-outline-primary\" for=\"btn\">Toggle</label>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1171, 'Bootstrap 5: Radio Button Group', 'Frontend', 1, 0.00, 'การสร้างปุ่มเลือกตัวเลือก Radio สไตล์ปุ่มกด', 'จำกัดการเลือกได้เพียงตัวเลือกเดียว', '<input type=\"radio\" class=\"btn-check\" name=\"r\"><label class=\"btn btn-outline-secondary\">Option</label>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1172, 'Bootstrap 5: Floating Labels Sizing', 'Frontend', 1, 0.00, 'การปรับขนาดช่องฟอร์มป้ายลอยตัว', 'กำหนดความสูงของช่องป้ายชื่อลอยให้พอดีกับเนื้อหา', '<div class=\"form-floating\"><input class=\"form-control form-control-sm\">...</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1173, 'Bootstrap 5: Navbar Text Align Utilities', 'Frontend', 1, 0.00, 'การจัดตำแหน่งข้อความภายใน Navbar', 'วางข้อความให้ชิดซ้ายขวาหรือจัดกึ่งกลาง', '<span class=\"navbar-text\">Logged in</span>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1174, 'Bootstrap 5: Navbar Offcanvas Integration', 'Frontend', 1, 0.00, 'การเปลี่ยน Navbar เป็นแถบ Offcanvas ในมือถือ', 'ประหยัดพื้นที่เมนูมือถือด้วยการสไลด์จากด้านข้าง', '<div class=\"offcanvas offcanvas-end\" id=\"offcanvasNavbar\">...</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1175, 'Bootstrap 5: Modal Backdrop Dynamic Toggle', 'Frontend', 1, 0.00, 'การเปิด-ปิดฉากหลังโมดอลด้วย JS', 'สั่งงานโมดอลผ่าน JavaScript โดยตรง', 'const modal = new bootstrap.Modal(\'#myModal\'); modal.show();', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1176, 'Bootstrap 5: Toast Stacking Vertically', 'Frontend', 1, 0.00, 'การซ้อนกล่องแจ้งเตือน Toast ในแนวตั้ง', 'แสดงแจ้งเตือนหลายรายการต่อกัน', '<div class=\"toast-container position-fixed bottom-0 end-0 p-3\">...</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1177, 'Bootstrap 5: Tooltip Custom HTML Content', 'Frontend', 1, 0.00, 'การใส่ HTML ลงในข้อความ Tooltip', 'แสดงรูปหรือข้อความเน้นพิเศษใน Tooltip', 'data-bs-html=\"true\" data-bs-title=\"<b>Bold</b> text\"', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1178, 'Bootstrap 5: Carousel Dark Text Variant', 'Frontend', 1, 0.00, 'การตั้งค่าข้อความในสไลเดอร์ให้เป็นสีเข้ม', 'ใช้สำหรับสไลด์แบนเนอร์พื้นหลังสีขาวหรืออ่อน', '<div class=\"carousel-caption d-none d-md-block text-dark\">...</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1179, 'Bootstrap 5: Dropdown Menu Custom Width', 'Frontend', 1, 0.00, 'การกำหนดความกว้างของดรอปดาวน์เมนู', 'บังคับขนาดเมนูตัวเลือกให้กว้างเป็นพิเศษ', '<ul class=\"dropdown-menu\" style=\"width: 300px;\">...</ul>', '2026-08-21 13:22:54', '2026-08-21 13:22:54');
INSERT INTO `component_items` (`id`, `name`, `category`, `stock`, `price`, `description`, `how_to_use`, `snippet`, `created_at`, `updated_at`) VALUES
(1180, 'Bootstrap 5: Grid Column Order First', 'Frontend', 1, 0.00, 'การบังคับคอลัมน์ให้อยู่ตำแหน่งแรกสุดเสมอ', 'จัดลำดับการแสดงผลคอลัมน์โดยไม่เปลี่ยนโครงสร้าง', '<div class=\"col order-first\">...</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1181, 'Bootstrap 5: Grid Column Order Last', 'Frontend', 1, 0.00, 'การบังคับคอลัมน์ให้อยู่ตำแหน่งท้ายสุด', 'ดันคอลัมน์สำคัญไปไว้ท้ายหน้าจอ', '<div class=\"col order-last\">...</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1182, 'Bootstrap 5: Flex Wrap Utilities (nowrap/wrap/reverse)', 'Frontend', 1, 0.00, 'การตั้งค่าการตัดบรรทัดไอเทม Flex', 'ป้องกันไอเทมทะลุขอบจอหรือสั่งให้ปัดตกบรรทัด', '<div class=\"d-flex flex-wrap\">...</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1183, 'Bootstrap 5: Flex Alignment Content', 'Frontend', 1, 0.00, 'การจัดแถวของ Flex หลายบรรทัด (align-content-start/end/center)', 'จัดการระยะห่างของแถวข้อมูลในพื้นที่ Flex', '<div class=\"d-flex flex-wrap align-content-around\">...</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1184, 'Bootstrap 5: Margin Negative X-Axis (mx-n1 to mx-n5)', 'Frontend', 1, 0.00, 'การกำหนดระยะขอบติดลบในแนวแกน X', 'ใช้ดึงคอนเทนต์ให้ซ้อนทับกันในแนวนอน', '<div class=\"mx-n2\">Overlapping box</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1185, 'Bootstrap 5: Margin Negative Y-Axis (my-n1 to my-n5)', 'Frontend', 1, 0.00, 'การกำหนดระยะขอบติดลบในแนวแกน Y', 'ดึงคอนเทนต์ขึ้นไปซ้อนทับด้านบน', '<div class=\"my-n2\">Pulled up item</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1186, 'Bootstrap 5: Background Image Overlay Opacity', 'Frontend', 1, 0.00, 'การทำพื้นหลังรูปภาพให้มืดลงด้วย Overlay', 'ใช้ซ้อนสีดำโปร่งแสงเหนือรูปภาพแบนเนอร์', '<div class=\"bg-dark bg-opacity-50\">...</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1187, 'Bootstrap 5: Border Color Primary Emphasis', 'Frontend', 1, 0.00, 'การใส่สีเส้นขอบสีหลักแบบเข้มข้น', 'ทำกรอบคอนเทนต์ให้โดดเด่นสะดุดตา', '<div class=\"border border-primary-emphasis\">...</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1188, 'Bootstrap 5: Rounded Top Start Bottom End', 'Frontend', 1, 0.00, 'การทำมุมโค้งมนเฉพาะด้าน (rounded-top-start)', 'ดีไซน์การ์ดให้มีความมนเพียงบางมุม', '<div class=\"rounded-top-start\">Rounded corner</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1189, 'Bootstrap 5: Shadow Extra Large (shadow-xl)', 'Frontend', 1, 0.00, 'การทำเงาขนาดใหญ่พิเศษ', 'ทำเงาฟุ้งกระจายใต้การ์ดที่ต้องการเน้นมากๆ', '<div class=\"shadow-xl\">Very deep shadow</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1190, 'Bootstrap 5: Text Emphasis Classes', 'Frontend', 1, 0.00, 'การทำสีตัวอักษรเน้นพิเศษ (text-primary-emphasis)', 'ใช้เน้นข้อความให้มีความเข้มขึ้นกว่าสีปกติ', '<p class=\"text-primary-emphasis\">Emphasis text</p>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1191, 'Bootstrap 5: Text Shadow Customization', 'Frontend', 1, 0.00, 'การใส่เงาให้ตัวหนังสือ (CSS style)', 'เพิ่มมิติให้หัวข้อภาษาไทยหรืออังกฤษ', '<h1 style=\"text-shadow: 1px 1px 2px #000;\">Shadowed text</h1>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
(1192, 'Bootstrap 5: Visibility Toggle Classes', 'Frontend', 1, 0.00, 'การซ่อนองค์ประกอบโดยยังเว้นพื้นที่ว่างไว้', 'ใช้สลับแสดงผลงานโดยไม่ทำให้เลย์เอาต์เคลื่อน', '<div class=\"invisible\">Hidden item</div>', '2026-08-21 13:22:54', '2026-08-21 13:22:54'),
