(2179, 'SwiftUI: LocalAuthentication FaceID Verification', 'Frontend', 1, 0.00, 'เรียกใช้งานระบบสแกนใบหน้าและความปลอดภัยใน UI', 'ตรวจสอบสิทธิ์ผู้ใช้ก่อนปลดล็อกหน้าจอสำคัญ', 'let context = LAContext(); context.evaluatePolicy(...)', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2180, 'SwiftUI: TipKit Contextual Onboarding Popups', 'Frontend', 1, 0.00, 'สร้างกล่องข้อความแนะนำฟีเจอร์ใหม่ให้ผู้ใช้', 'สอนวิธีใช้งานปุ่มต่างๆ ในแอปอย่างเป็นมิตร', 'struct TipView: Tip { var title: Text { ... } }', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2181, 'Database: B-Tree Index Internal Structure', 'Backend', 1, 0.00, 'ทำความเข้าใจโครงสร้างการจัดเก็บ Index แบบ B-Tree', 'ช่วยให้เข้าใจวิธีการค้นหาข้อมูลระดับลึกในตาราง', 'CREATE INDEX idx_users_name ON users(name);', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2182, 'Database: Composite Index Column Order Strategy', 'Backend', 1, 0.00, 'การเรียงลำดับคอลัมน์ในคอมโพสิตอินเดกซ์', 'เพิ่มประสิทธิภาพการค้นหาเมื่อมีเงื่อนไขหลายคอลัมน์พร้อมกัน', 'CREATE INDEX idx_city_age ON users(city, age);', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2183, 'Database: Covering Index Optimization', 'Backend', 1, 0.00, 'การสร้าง Index ที่ครอบคลุมฟิลด์ทั้งหมดในคำสั่ง Query', 'ดึงข้อมูลจาก Index โดยตรงโดยไม่ต้องอ่านตารางหลัก (Table Scan)', 'SELECT name, age FROM users WHERE city = \"Bangkok\";', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2184, 'Database: Clustered vs Non-Clustered Indexes', 'Backend', 1, 0.00, 'ความแตกต่างระหว่างดัชนีแบบคลัสเตอร์และไม่เป็นคลัสเตอร์', 'การจัดเก็บข้อมูลจริงในดิสก์เทียบกับตัวชี้ตำแหน่ง', 'Primary Key creates a Clustered Index automatically', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2185, 'Database: Query Execution Plan Analysis (EXPLAIN)', 'Backend', 1, 0.00, 'การตรวจสอบแผนผังการทำงานของคำสั่ง SQL', 'วิเคราะห์ว่า Query ใช้ Index หรือเกิด Full Table Scan', 'EXPLAIN SELECT * FROM orders WHERE status = 1;', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2186, 'Database: Deadlock Prevention and Detection', 'Backend', 1, 0.00, 'การป้องกันและตรวจจับปัญหาการชนกันของทรานซิชัน', 'ออกแบบลำดับการล็อกตารางเพื่อไม่ให้ระบบค้าง', 'SHOW ENGINE INNODB STATUS;', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2187, 'Database: ACID Properties Deep Dive', 'Backend', 1, 0.00, 'หลักการความปลอดภัยของฐานข้อมูล (Atomicity, Consistency, Isolation, Durability)', 'รับประกันความถูกต้องของข้อมูลทุกธุรกรรม', 'BEGIN TRANSACTION; ... COMMIT;', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2188, 'Database: Isolation Levels (Read Committed / Serializable)', 'Backend', 1, 0.00, 'การกำหนดระดับการแยกธุรกรรมเพื่อป้องกันข้อมูลเพี้ยน', 'แก้ปัญหา Dirty Read, Non-repeatable Read และ Phantom Read', 'SET TRANSACTION ISOLATION LEVEL READ COMMITTED;', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2189, 'Database: Partitioning Large Tables by Range', 'Backend', 1, 0.00, 'การแบ่งตารางขนาดใหญ่ออกเป็นพาร์ติชันย่อยตามช่วงเวลา', 'เร่งความเร็วการค้นหาข้อมูลประวัติหรือล็อกย้อนหลัง', 'CREATE TABLE logs (...) PARTITION BY RANGE (YEAR(created_at)) (...);', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2190, 'Database: Database Sharding Horizontal Scaling', 'Backend', 1, 0.00, 'การกระจายข้อมูลตารางออกไปยังหลายเซิร์ฟเวอร์', 'รองรับปริมาณข้อมูลมหาศาลระดับหลายร้อยล้านแถว', 'Shard key routing architecture', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2191, 'Database: Connection Pooling Configuration', 'Backend', 1, 0.00, 'การจัดการสระเชื่อมต่อฐานข้อมูลเพื่อลดเวลาเปิดปิด', 'ใช้ซ้ำการเชื่อมต่อเดิมเพื่อรองรับคำขอจำนวนมาก', 'max_connections = 200, pool_size = 50', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2192, 'Database: Slow Query Log Analysis', 'Backend', 1, 0.00, 'การบันทึกคำสั่ง SQL ที่ใช้เวลานานเกินกำหนด', 'ค้นหาจุดบกพร่องเพื่อนำมาปรับปรุงดัชนี', 'slow_query_log = 1, long_query_time = 2', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2193, 'Database: Full-Text Search Indexing', 'Backend', 1, 0.00, 'การทำดัชนีค้นหาข้อความเต็มรูปแบบในภาษาธรรมชาติ', 'ค้นหาคำศัพท์ในบทความหรือชื่อสินค้าได้อย่างรวดเร็ว', 'CREATE FULLTEXT INDEX idx_desc ON products(description);', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2194, 'Database: Stored Procedures and Functions', 'Backend', 1, 0.00, 'การเขียนโปรแกรมเก็บไว้ในฐานข้อมูล', 'ลดการส่งผ่านข้อมูลเครือข่ายและประมวลผลฝั่งเซิร์ฟเวอร์ SQL', 'CREATE PROCEDURE GetUserOrders(IN userId INT) BEGIN ... END;', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2195, 'Database: Database Triggers for Audit Logging', 'Backend', 1, 0.00, 'การสร้างทริกเกอร์เพื่อบันทึกประวัติการแก้ไขข้อมูล', 'ตรวจสอบอัตโนมัติเมื่อมีการ INSERT, UPDATE, หรือ DELETE', 'CREATE TRIGGER log_user_update AFTER UPDATE ON users FOR EACH ROW ...', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2196, 'Database: Database Normalization (1NF to 3NF)', 'Backend', 1, 0.00, 'กฎการจัดระเบียบตารางเพื่อลดความซ้ำซ้อนของข้อมูล', 'ออกแบบความสัมพันธ์ตารางให้สะอาดและถูกต้องตามหลักสากล', 'Eliminate repeating groups and transitive dependencies', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2197, 'Database: Database Denormalization for Speed', 'Backend', 1, 0.00, 'การรวมตารางเพื่อเร่งความเร็วในการอ่านข้อมูล', 'ยอมให้ข้อมูลซ้ำเล็กน้อยเพื่อแลกกับความเร็วในการ Query', 'Storing summary counts directly in parent tables', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2198, 'Database: JSON Data Type Optimization in SQL', 'Backend', 1, 0.00, 'การจัดเก็บและค้นหาข้อมูลรูปแบบ JSON ในตารางเชิงสัมพันธ์', 'ยืดหยุ่นในการเก็บข้อมูลย่อยที่ไม่แน่นอน', 'SELECT * FROM users WHERE settings->> \"$.theme\" = \"dark\";', '2026-08-21 13:42:22', '2026-08-21 13:42:22');
INSERT INTO `component_items` (`id`, `name`, `category`, `stock`, `price`, `description`, `how_to_use`, `snippet`, `created_at`, `updated_at`) VALUES
(2199, 'Database: Database Replication (Master-Slave)', 'Backend', 1, 0.00, 'การสำรองและจำลองข้อมูลจากเซิร์ฟเวอร์หลักไปยังเซิร์ฟเวอร์ลูก', 'กระจายโหลดการอ่านข้อมูลออกไปหลายเครื่อง', 'Master for write, Slaves for read queries', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2200, 'Database: Backup Strategy with Point-in-Time Recovery', 'Backend', 1, 0.00, 'กลยุทธ์การสำรองข้อมูลเพื่อกู้คืนในวินาทีที่ต้องการ', 'ป้องกันความเสียหายสูงสุดเมื่อเกิดระบบล่ม', 'Binary log backups and daily full dumps', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2201, 'DevOps: VS Code Custom Keyboard Shortcuts', 'Backend', 1, 0.00, 'การตั้งค่าคีย์ลัดส่วนตัวใน VS Code เพื่อความเร็วสูงสุด', 'ลดเวลาการเอื้อมมือใช้เมาส์ระหว่างเขียนโค้ด', 'keybindings.json configuration', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2202, 'DevOps: VS Code Multi-Cursor Editing Tricks', 'Backend', 1, 0.00, 'การใช้เคอร์เซอร์หลายจุดแก้ไขโค้ดพร้อมกัน', 'เปลี่ยนชื่อตัวแปรหรือแก้ข้อความหลายบรรทัดในพริบตา', 'Alt + Click / Ctrl + Alt + Down', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2203, 'DevOps: VS Code GitLens Extension Power', 'Backend', 1, 0.00, 'การใช้งานเครื่องมือ Git ขั้นสูงใน VS Code', 'ตรวจสอบว่าใครเป็นคนแก้โค้ดบรรทัดนี้และเมื่อไหร่', 'GitLens: Blame annotations in editor', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2204, 'DevOps: VS Code Workspace Settings Management', 'Backend', 1, 0.00, 'การตั้งค่าคอนฟิกแยกตามโปรเจกต์งาน', 'กำหนดสไตล์โค้ด (Prettier/ESLint) เฉพาะโปรเจกต์', '.vscode/settings.json setup', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2205, 'DevOps: Git Rebase Interactive Workflow', 'Backend', 1, 0.00, 'การรวมและจัดระเบียบประวัติการคอมมิตให้สะอาด', 'รวมหลายคอมมิตเป็นก้อนเดียวก่อนส่ง Pull Request', 'git rebase -i HEAD~5', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2206, 'DevOps: Git Cherry-Pick Specific Commits', 'Backend', 1, 0.00, 'การดึงเฉพาะคอมมิตที่ต้องการข้าม Branch', 'นำการแก้ไขจากสาขาอื่นมาใช้โดยไม่ต้องรวมทั้ง Branch', 'git cherry-pick <commit-hash>', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2207, 'DevOps: Git Stash Pop and Management', 'Backend', 1, 0.00, 'การเก็บและเรียกคืนงานที่พักไว้ชั่วคราว', 'สลับไปแก้บั๊กกะทันหันแล้วกลับมาทำงานเดิมต่อ', 'git stash push -m \"work in progress\" && git stash pop', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2208, 'DevOps: Git Submodules Management', 'Backend', 1, 0.00, 'การดึงโปรเจกต์อื่นมาเป็นส่วนหนึ่งของ repository', 'จัดการโค้ดที่ต้องใช้ร่วมกันหลายโปรเจกต์', 'git submodule add <repository-url>', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2209, 'DevOps: GitHub Actions CI/CD Pipeline Setup', 'Backend', 1, 0.00, 'การตั้งค่าระบบรันเทสต์และอัปเดตอัตโนมัติ', 'ตรวจสอบโค้ดทุกครั้งที่มีการ Pull Request', '.github/workflows/main.yml configuration', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2210, 'DevOps: Dockerfile Multi-stage Builds', 'Backend', 1, 0.00, 'การสร้างภาพคอนเทนเนอร์ด้วยเทคนิคหลายสเตจ', 'ลดขนาดไฟล์ Docker image ให้เล็กที่สุดเพื่อความปลอดภัย', 'FROM node:18 AS build ... COPY --from=build /app/dist', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2211, 'DevOps: Docker Compose Healthchecks', 'Backend', 1, 0.00, 'การตรวจสอบสถานะความพร้อมของบริการใน Docker', 'สั่งให้เว็บแอปเริ่มทำงานหลังจากฐานข้อมูลพร้อมใช้งานจริง', 'healthcheck: test: [\"CMD\", \"mysqladmin\", \"ping\"]', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2212, 'DevOps: Nginx Reverse Proxy Configuration', 'Backend', 1, 0.00, 'การตั้งค่า Nginx เป็นพร็อกซี่ส่งต่อคำขอ', 'จัดการโดเมนและส่งต่อคำขอไปยัง Laravel หรือ Node.js', 'proxy_pass http://127.0.0.1:8000;', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2213, 'DevOps: Let\'s Encrypt SSL Auto-Renewal', 'Backend', 1, 0.00, 'การต่ออายุใบรับรองความปลอดภัย HTTPS อัตโนมัติ', 'ป้องกันเว็บไซต์หมดอายุความปลอดภัย', 'certbot renew --quiet', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2214, 'DevOps: Linux Firewall (UFW) Security Setup', 'Backend', 1, 0.00, 'การตั้งค่าไฟร์วอลล์ป้องกั้นพอร์ตที่ไม่จำเป็นบนเซิร์ฟเวอร์', 'เปิดเฉพาะพอร์ต 80, 443 และ SSH ที่จำเป็น', 'ufw allow 22 && ufw allow \'Nginx Full\' && ufw enable', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2215, 'DevOps: Systemd Service Management for Apps', 'Backend', 1, 0.00, 'การสร้างบริการรันแอปพลิเคชันให้ทำงานตลอดเวลา', 'รีสตาร์ทแอปอัตโนมัติหากเซิร์ฟเวอร์รีบูตหรือแอปพัง', 'systemctl enable my-laravel-app.service', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2216, 'DevOps: Logrotate Configuration for Disk Space', 'Backend', 1, 0.00, 'การจัดการไฟล์ล็อกระบบไม่ให้กินพื้นที่ดิสก์จนเต็ม', 'บีบอัดและลบไฟล์ล็อกเก่าตามรอบเวลา', '/etc/logrotate.d/myapp configuration', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2217, 'DevOps: Environment Variable Vault Management', 'Backend', 1, 0.00, 'การจัดเก็บข้อมูลความลับของระบบอย่างปลอดภัย', 'เข้ารหัสและจำกัดสิทธิ์การเข้าถึงไฟล์คอนฟิก', 'Secure secret management practices', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2218, 'DevOps: Automated Database Backups Script', 'Backend', 1, 0.00, 'การเขียนสคริปต์สำรองฐานข้อมูลส่งขึ้น Cloud S3', 'ประกันความปลอดภัยข้อมูลไม่ให้สูญหาย', 'mysqldump db | gzip > backup.sql.gz && aws s3 cp ...', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2219, 'DevOps: Server Performance Monitoring (htop/iotop)', 'Backend', 1, 0.00, 'การตรวจสอบทรัพยากรซีพียู หน่วยความจำ และดิสก์', 'วิเคราะห์ปัญหาเมื่อเซิร์ฟเวอร์ทำงานช้าหรือแฮงก์', 'htop and iotop utility monitoring', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2220, 'DevOps: Zero-Downtime Deployment Strategy', 'Backend', 1, 0.00, 'การอัปเดตระบบโดยผู้ใช้ไม่รู้สึกว่าเว็บสะดุด', 'สลับเวอร์ชันโค้ดใหม่ทันทีโดยไม่มีช่วงเวลาออฟไลน์', 'Symlink release folder atomic deployment', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2221, 'Laravel: Pipeline Middleware Stage Pattern', 'Backend', 1, 0.00, 'การสร้างระบบท่อส่งข้อมูลผ่านสเตจขั้นบันได', 'ใช้สำหรับตรวจสอบคำขอผ่านชั้นกรองหลายรอบ', 'app(Pipeline::class)->send($data)->through([...])->thenReturn()', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2222, 'Laravel: Eloquent WhereHasMorph Advanced Query', 'Backend', 1, 0.00, 'การค้นหาข้อมูลความสัมพันธ์แบบ Polymorphic ซับซ้อน', 'ดึงข้อมูลที่เชื่อมโยงกับโมเดลหลากหลายรูปแบบได้อย่างแม่นยำ', 'User::whereHasMorph(\'commentable\', [Post::class], function ($q) { ... })->get()', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2223, 'Laravel: Custom Validation Rule Object Classes', 'Backend', 1, 0.00, 'การสร้างคลาสเงื่อนไขตรวจสอบฟอร์มเฉพาะตัว', 'เขียนตรรกะตรวจสอบข้อมูลซับซ้อนที่ใช้งานข้ามฟอร์ม', 'php artisan make:rule Uppercase', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
(2224, 'Laravel: Response Macro Creation in ServiceProvider', 'Backend', 1, 0.00, 'การสร้างเมธอดตอบกลับ HTTP Response สำเร็จรูป', 'ส่งรูปแบบ JSON มาตรฐานทั่วทั้งระบบได้อย่างรวดเร็ว', 'Response::macro(\'success\', function ($data) { return Response::json([...]); })', '2026-08-21 13:42:22', '2026-08-21 13:42:22'),
