(2359, 'React: useDeferredValue Search Filtering Optimization', 'Frontend', 1, 0.00, 'หน่วงการกรองข้อมูลรายการยาวๆ ตอนผู้ใช้พิมพ์ค้นหา', 'รักษาความเร็วการตอบสนองของ UI ในเว็บแอป', 'const filtered = useDeferredValue(items);', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2360, 'React: useTransition Tab Switching Non-blocking', 'Frontend', 1, 0.00, 'สลับแท็บหน้าจอเว็บแอปแบบไม่กระตุกด้วย useTransition', 'ให้แอปตอบสนองการกดปุ่มทันทีก่อนเรนเดอร์หน้าใหม่', 'startTransition(() => { setActiveTab(tab); });', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2361, 'React: useId Form Input Label Association', 'Frontend', 1, 0.00, 'สร้างไอดีอัตโนมัติสำหรับฟอร์ม accessibility มาตรฐาน', 'เชื่อมป้ายข้อความกับช่องกรอกข้อมูลให้ถูกต้อง', '<label htmlFor={id}>Name</label><input id={id} />', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2362, 'React: Component Composition Slot Content Injection', 'Frontend', 1, 0.00, 'การใส่คอมโพเนนต์ย่อยผ่านช่อง Slot ของแม่', 'ออกแบบโครงสร้างหน้าจอให้รองรับเนื้อหาหลากหลาย', 'function Layout({ top, bottom }) { ... }', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2363, 'React: Polymorphic Element Render Custom Tag', 'Frontend', 1, 0.00, 'เรนเดอร์คอมโพเนนต์เป็นแท็ก HTML ใดก็ได้ตามต้องการ', 'สร้างคอมโพเนนต์ยืดหยุ่นสูงสำหรับใช้ซ้ำทั่วโปรเจกต์', 'createElement(as, props, children)', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2364, 'React: State Reducer Action Dispatch Architecture', 'Frontend', 1, 0.00, 'จัดการสเตจซับซ้อนด้วยสถาปัตยกรรม Reducer', 'ควบคุมการเปลี่ยนแปลงข้อมูลภายในคอมโพเนนต์อย่างเป็นระบบ', 'switch (action.type) { case \'SET\': return ... }', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2365, 'React: Tailwind CSS Arbitrary Value Modifiers', 'Frontend', 1, 0.00, 'การใช้งานค่าพิกัดตามใจชอบใน Tailwind CSS', 'กำหนดขนาดหรือสีเฉพาะตัวที่ไม่มียูทิลิตี้พื้นฐาน', '<div className=\"top-[117px] bg-[#123456]\">', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2366, 'SwiftUI: Custom Layout Protocol Subviews Geometry', 'Frontend', 1, 0.00, 'คำนวณตำแหน่งย่อยของซับวิวใน Custom Layout', 'จัดเรียงคอมโพเนนต์รูปแบบเรขาคณิตซับซ้อน', 'func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ())', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2367, 'SwiftUI: AnimatableData Vector Arithmetic Multi-Float', 'Frontend', 1, 0.00, 'จัดการค่าตัวเลขหลายตัวใน AnimatableData พร้อมกัน', 'ทำแอนิเมชันเปลี่ยนรูปร่างกราฟิกหลายมิติ', 'var animatableData: AnimatablePair<CGFloat, CGFloat>', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2368, 'SwiftUI: AnyTransition Modifier Active Identity Setup', 'Frontend', 1, 0.00, 'กำหนดสเตจเริ่มต้นและสิ้นสุดของ Custom Transition', 'ควบคุมการเปิดปิดหน้าจอแอนิเมชันสไตล์เฉพาะตัว', 'AnyTransition.modifier(active: ActiveView(), identity: IdentityView())', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2369, 'SwiftUI: Canvas GraphicsContext Fill Path Operations', 'Frontend', 1, 0.00, 'วาดและเติมสีลงในเส้นทาง Path ผ่าน Canvas Context', 'สร้างกราฟิกรูปทรงเรขาคณิตความเร็วสูง', 'context.fill(path, with: .linearGradient(...))', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2370, 'SwiftUI: TimelineView Periodic Date Interval Update', 'Frontend', 1, 0.00, 'อัปเดตข้อมูลหน้าจอตามช่วงเวลาวินาทีที่กำหนด', 'ทำนาฬิกาหรือตัวจับเวลาเรียลไทม์ใน SwiftUI', 'TimelineView(.periodic(from: .now, by: 1)) { context in ... }', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2371, 'SwiftUI: VisualEffect Container Proxy Geometry Reader', 'Frontend', 1, 0.00, 'อ่านค่าพิกัดการเลื่อนหน้าจอผ่าน VisualEffect Proxy', 'ทำเอฟเฟกต์แบนเนอร์ยืดหดตามการปัดนิ้ว', '.visualEffect { content, proxy in ... }', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2372, 'SwiftUI: ScrollTransition Phase Identity Inspection', 'Frontend', 1, 0.00, 'ตรวจสอบสถานะ Phase ของการ์ดขณะเลื่อน ScrollView', 'คำนวณขนาดการ์ดตามตำแหน่งการแสดงผลบนจอ', 'if phase.isIdentity { ... }', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2373, 'SwiftUI: EnvironmentValues Custom Key Default Provider', 'Frontend', 1, 0.00, 'ประกาศค่าเริ่มต้นให้ Environment Custom Key', 'ป้องกันข้อผิดพลาดกรณีไม่มีการส่งค่าคอนฟิกเข้ามา', 'static var defaultValue: String = \"Default\"', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2374, 'SwiftUI: ViewThatFits Horizontal Vertical Fallback', 'Frontend', 1, 0.00, 'สลับเลย์เอาต์แนวนอนและแนวตั้งอัตโนมัติเมื่อพื้นที่ไม่พอ', 'ป้องกันปัญหาคอนเทนต์ล้นจอในหน้าจอขนาดเล็ก', 'ViewThatFits { HStack { ... }; VStack { ... } }', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2375, 'SwiftUI: Namespace MatchedGeometryEffect ID Scoping', 'Frontend', 1, 0.00, 'ควบคุมขอบเขตไอดีของ MatchedGeometryEffect', 'ป้องกันแอนิเมชันตีกันเมื่อมีหลายคอมโพเนนต์ในหน้า', '@Namespace private var ns', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2376, 'Database: B-Tree Index Leaf Node Double Linking', 'Backend', 1, 0.00, 'โครงสร้างโหนดใบเชื่อมโยงคู่ในดัชนี B-Tree', 'เร่งความเร็วการค้นหาข้อมูลแบบช่วงเรียงลำดับ', 'Doubly linked leaf nodes for efficient range traversal', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2377, 'Database: Composite Index Selectivity Evaluation', 'Backend', 1, 0.00, 'การประเมินค่าการเลือกสรร (Selectivity) ของคอมโพสิตอินเดกซ์', 'หลักการเลือกคอลัมน์ที่มีความหลากหลายสูงมาไว้หน้า', 'High cardinality columns should be placed first', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2378, 'Database: Covering Index Extra Lookup Elimination', 'Backend', 1, 0.00, 'การตัดขั้นตอนการดึงข้อมูลตารางหลักด้วย Covering Index', 'เพิ่มความเร็วสูงสุดโดยอ่านข้อมูลจาก Index จบในตัว', 'Avoids Bookmark Lookup / Row ID lookup', '2026-08-21 13:44:27', '2026-08-21 13:44:27');
INSERT INTO `component_items` (`id`, `name`, `category`, `stock`, `price`, `description`, `how_to_use`, `snippet`, `created_at`, `updated_at`) VALUES
(2379, 'Database: Primary Key Clustered Index Ordering', 'Backend', 1, 0.00, 'การจัดเรียงข้อมูลทางกายภาพบนดิสก์ตาม Primary Key', 'เพิ่มประสิทธิภาพการเข้าถึงข้อมูลแบบสุ่มและเรียงลำดับ', 'Clustered index defines physical row order', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2380, 'Database: EXPLAIN Query Cost Estimation Metrics', 'Backend', 1, 0.00, 'การวิเคราะห์ค่าใช้จ่ายและต้นทุนคำสั่ง Query จาก EXPLAIN', 'ประเมินประสิทธิภาพทรัพยากรที่ใช้ในการประมวลผล', 'cost and rows estimation in optimizer output', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2381, 'Database: Innodb Lock Table Concurrency Management', 'Backend', 1, 0.00, 'การจัดการการล็อกตารางระดับแถวใน InnoDB', 'เพิ่มความสามารถในการรองรับการเขียนข้อมูลพร้อมกัน', 'Row-level locking mechanisms for high concurrency', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2382, 'Database: Transaction Isolation Snapshot Read', 'Backend', 1, 0.00, 'การอ่านข้อมูลแบบภาพถ่ายสแนปชอตในทรานซิชัน', 'รับประกันความสอดคล้องของข้อมูลระหว่างอ่านและเขียน', 'Consistent non-locking reads in Repeatable Read', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2383, 'Database: Table Partitioning List Strategy Configuration', 'Backend', 1, 0.00, 'การแบ่งพาร์ติชันตารางตามกลุ่มรายการข้อมูล (List)', 'จัดเก็บข้อมูลแยกตามหมวดหมู่โซนหรือภูมิภาค', 'CREATE TABLE sales (...) PARTITION BY LIST (region_id) (...);', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2384, 'Database: Distributed Database Sharding Routing', 'Backend', 1, 0.00, 'การกำหนดเส้นทางการเข้าถึงข้อมูลในระบบ Sharding', 'ส่งคำขอไปยังโหนดฐานข้อมูลที่ถูกต้องตามคีย์กระจาย', 'Routing algorithm based on sharding keys', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2385, 'Database: Persistent Connection Pool Management', 'Backend', 1, 0.00, 'การรักษาการเชื่อมต่อฐานข้อมูลแบบถาวรในพูล', 'ลดภาระเวลาในการสร้างการเชื่อมต่อใหม่ทุกคำขอ', 'Persistent connection reuse pattern', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2386, 'DevOps: VS Code Extension Development Environment', 'Backend', 1, 0.00, 'การตั้งค่าสภาพแวดล้อมสำหรับพัฒนาส่วนเสริม VS Code', 'เขียน Extension เพิ่มความสามารถเฉพาะตัวให้โปรแกรม', 'yo code generator and extension manifest', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2387, 'DevOps: VS Code Debugger Configuration Launch JSON', 'Backend', 1, 0.00, 'การตั้งค่าไฟล์ launch.json สำหรับดีบักโปรเจกต์', 'กำหนดพารามิเตอร์และจุดเริ่มต้นการรันดีบักโค้ด', '.vscode/launch.json setup for debugging', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2388, 'DevOps: Git Bisect Binary Search Bug Finding', 'Backend', 1, 0.00, 'การค้นหาคอมมิตที่ทำให้เกิดบั๊กด้วยวิธีค้นหาแบบทวิภาค', 'ไล่หาจุดผิดพลาดในประวัติ Git จำนวนมากลงได้อย่างรวดเร็ว', 'git bisect start -> git bisect bad -> git bisect good', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2389, 'DevOps: Git Filter-Repo History Sanitization', 'Backend', 1, 0.00, 'การลบไฟล์ความลับหรือรหัสผ่านออกจากประวัติ Git ทั้งหมด', 'ทำความสะอาดประวัติคอมมิตก่อนเปิดซอร์สโค้ดเป็นสาธารณะ', 'git filter-repo --path secret.txt --invert-path', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2390, 'DevOps: GitHub Actions Matrix Build Strategy', 'Backend', 1, 0.00, 'การรันเทสต์ข้ามหลายเวอร์ชันระบบปฏิบัติการและภาษา', 'ตรวจสอบความเข้ากันได้ของซอฟต์แวร์ในหลายสภาพแวดล้อม', 'strategy: matrix: os: [ubuntu-latest, macos-latest]', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2391, 'DevOps: Docker Multi-Architecture Buildx Tool', 'Backend', 1, 0.00, 'การสร้างอิมเมจ Docker รองรับหลายสถาปัตยกรรม (AMD64/ARM64)', 'คอมไพล์แอปให้รันได้ทั้งบนชิป Intel และ Apple Silicon / AWS Graviton', 'docker buildx build --platform linux/amd64,linux/arm64', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2392, 'DevOps: Docker Compose Depends On Condition Health', 'Backend', 1, 0.00, 'การตั้งค่าเงื่อนไขความพร้อมบริการใน Docker Compose', 'รอให้ฐานข้อมูลส่งสัญญาณพร้อมใช้งานก่อนรันเว็บแอป', 'depends_on: db: condition: service_healthy', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2393, 'DevOps: Nginx Upstream Load Balancing Configuration', 'Backend', 1, 0.00, 'การตั้งค่ากระจายโหลดคำขอไปยังเซิร์ฟเวอร์แอปหลายเครื่อง', 'เพิ่มความเสถียรและรองรับผู้ใช้จำนวนมหาศาล', 'upstream backend { server 10.0.0.1; server 10.0.0.2; }', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2394, 'DevOps: Let\'s Encrypt DNS Challenge Automation', 'Backend', 1, 0.00, 'การขอใบรับรอง SSL ผ่าน DNS API อัตโนมัติ', 'ออกใบรับรองสำหรับเซิร์ฟเวอร์ที่อยู่หลังไฟร์วอลล์ภายใน', 'certbot certonly --authenticator dns-route53', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2395, 'DevOps: Linux Kernel Swappiness Tuning Parameter', 'Backend', 1, 0.00, 'การปรับแต่งความถี่ในการใช้งาน Swap Space ของลินุกซ์', 'ควบคุมการใช้งานหน่วยความจำสำรองให้มีประสิทธิภาพสูงสุด', 'sysctl vm.swappiness=10', '2026-08-21 13:44:27', '2026-08-21 13:44:27'),
(2396, 'Laravel: Pipeline Payload Stage', 'Backend', 1, 0.00, 'การแปลงสภาพข้อมูลระหว่างเดินทางผ่านท่อ Pipeline', 'ปรับแต่งโครงสร้างข้อมูลในแต่ละขั้นตอนการประมวลผล', 'return $next($payload->toNormalized());', '2026-08-21 13:47:01', '2026-08-21 13:47:01'),
(2397, 'Laravel: Eloquent MorphTo Constraint', 'Backend', 1, 0.00, 'การดึงข้อมูลความสัมพันธ์ Polymorphic แบบจำกัดเงื่อนไข', 'โหลดข้อมูลความสัมพันธ์หลายรูปแบบพร้อมกรองเฉพาะที่ต้องการ', '$posts = Post::with([\'commentable\' => function ($morphTo) { ... }])->get();', '2026-08-21 13:47:01', '2026-08-21 13:47:01'),
(2398, 'Laravel: Custom Validation Rule', 'Backend', 1, 0.00, 'การสร้างเงื่อนไขตรวจสอบฟอร์มที่ต้องอิงกับฟิลด์อื่น', 'บังคับให้ฟิลด์หนึ่งต้องกรอกก็ต่อเมื่ออีกฟิลด์มีค่าตามกำหนด', 'Rule::requiredIf(fn () => request(\'type\') === \'special\')', '2026-08-21 13:47:01', '2026-08-21 13:47:01'),
(2399, 'Laravel: Response Macro Paginated', 'Backend', 1, 0.00, 'การสร้างเมธอดตอบกลับข้อมูลแบบแบ่งหน้ามาตรฐาน', 'จัดระเบียบโครงสร้าง JSON สำหรับข้อมูลที่มี Pagination', 'Response::macro(\'paginated\', function ($data) { return [...]; })', '2026-08-21 13:47:01', '2026-08-21 13:47:01'),
(2400, 'Laravel: Model Factories Sequence', 'Backend', 1, 0.00, 'การสร้างข้อมูลจำลองแบบเรียงลำดับต่อเนื่องใน Factory', 'สร้างค่าตัวเลขหรือชื่อที่เปลี่ยนไปตามลำดับการรัน', 'User::factory()->count(10)->sequence(fn ($seq) => [\'role\' => $seq->index % 2 ? \'admin\' : \'user\'])->create()', '2026-08-21 13:47:01', '2026-08-21 13:47:01'),
(2401, 'Laravel: View Composers Multiple Sharing', 'Backend', 1, 0.00, 'การแชร์ข้อมูลให้หน้าเทมเพลต Blade หลายหน้าพร้อมกัน', 'ส่งตัวแปรส่วนกลางไปยังทุกหน้าจอในกลุ่มที่กำหนด', 'View::composer([\'profile\', \'settings\'], ProfileComposer::class)', '2026-08-21 13:47:01', '2026-08-21 13:47:01'),
